// Code - Validate, Price & Decide Stage
// LANDOC Marriage Registration V2 - Safe validated version
// Updated for:
// 1. Existing Odoo bot + WhatsApp bot compatibility
// 2. New Odoo Marriage Registration Options API flow
// 3. Service options + registration place options from Odoo
// 4. Fee calculation only after service + registration place selection
// 5. Existing lead/payment/document flow preserved

const rawInput = $input.first().json || {};

// Try to read original inbound context from service trigger/debug node
let inbound = {};
try {
  inbound = $('SET_Debug_Inbound_Context').item.json || {};
} catch (e) {
  inbound = {};
}

// --------------------------------------------------
// Helpers
// --------------------------------------------------

function isObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value);
}

function parseMaybeJson(value) {
  if (!value) return {};

  if (isObject(value)) return value;

  if (typeof value !== 'string') return {};

  let cleaned = value
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    const parsed = JSON.parse(cleaned);
    return isObject(parsed) ? parsed : {};
  } catch (e) {
    return {};
  }
}

function pick(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return value;
    }
  }
  return '';
}

function toBool(value) {
  return value === true || value === 'true';
}

function normalizeLanguage(value) {
  const v = String(value || '').trim().toLowerCase();

  if (v.includes('tamil') || v === 'ta' || v === 'தமிழ்') return 'Tamil';
  if (v.includes('tanglish')) return 'Tanglish';

  return 'English';
}

function normalizeMobile(value) {
  return String(value || '').replace(/\D/g, '').slice(-10);
}

function isValidMobile(value) {
  return /^[6-9]\d{9}$/.test(String(value || '').trim());
}

function normalizeDateInput(value) {
  const raw = String(value || '').trim();

  if (/^\d{2}\/\d{2}\/\d{4}$/.test(raw)) return raw;

  const m = raw.match(/^(\d{2})[-.](\d{2})[-.](\d{4})$/);
  if (m) return `${m[1]}/${m[2]}/${m[3]}`;

  return raw;
}

function isValidDateFormat(value) {
  return /^\d{2}\/\d{2}\/\d{4}$/.test(String(value || '').trim());
}

function parseDDMMYYYY(dateStr) {
  const normalized = normalizeDateInput(dateStr);
  if (!isValidDateFormat(normalized)) return null;

  const [dd, mm, yyyy] = String(normalized).split('/').map(Number);
  const d = new Date(yyyy, mm - 1, dd);

  if (
    d.getFullYear() !== yyyy ||
    d.getMonth() !== mm - 1 ||
    d.getDate() !== dd
  ) {
    return null;
  }

  return d;
}

function calculateAge(dob) {
  const d = parseDDMMYYYY(dob);
  if (!d) return null;

  const today = new Date();
  let age = today.getFullYear() - d.getFullYear();
  const m = today.getMonth() - d.getMonth();

  if (m < 0 || (m === 0 && today.getDate() < d.getDate())) {
    age--;
  }

  return age;
}

function marriageAgeDays(marriageDate) {
  const d = parseDDMMYYYY(marriageDate);
  if (!d) return null;

  const today = new Date();
  const diffMs = today.getTime() - d.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

function normalizeReligion(value) {
  const v = String(value || '').trim().toLowerCase();

  if (v === '1' || v.includes('hindu')) return 'Hindu';
  if (v === '2' || v.includes('muslim') || v.includes('islam')) return 'Muslim';
  if (v === '3' || v.includes('christian')) return 'Christian';
  if (v === '4' || v.includes('other')) return 'Other';

  return String(value || '').trim();
}

function normalizeReligionForOptions(value) {
  const v = String(value || '').trim().toLowerCase();

  if (v === '1' || v.includes('hindu')) return 'hindu';
  if (v === '2' || v.includes('muslim') || v.includes('islam')) return 'muslim';
  if (v === '3' || v.includes('christian')) return 'christian';
  if (v === '4' || v.includes('other')) return 'other';

  return v;
}

function normalizeMarriageDateForApi(value) {
  return normalizeDateInput(value);
}

function getServiceCategory(brideReligion, groomReligion) {
  const bride = normalizeReligion(brideReligion);
  const groom = normalizeReligion(groomReligion);

  if (bride === 'Hindu' && groom === 'Hindu') return 'Hindu Marriage';
  if (bride === 'Muslim' && groom === 'Muslim') return 'Muslim Marriage';
  if (bride === 'Christian' && groom === 'Christian') return 'Christian Marriage';
  if (bride && groom && bride !== groom) return 'Special Marriage';

  return 'Need Team Verification';
}

function getServiceCost(marriageDate) {
  const days = marriageAgeDays(marriageDate);
  const cost = days !== null && days > 150 ? 7500 : 6000;

  return {
    cost,
    formatted: `₹${cost.toLocaleString('en-IN')}`,
    days_from_marriage: days,
    exceeds_150_days: days !== null && days > 150
  };
}

function toServiceCode(serviceCategoryOrOption) {
  const value = String(serviceCategoryOrOption || '').trim().toLowerCase();

  if (value.includes('both')) return 'hindu_and_tamilnadu_marriage';
  if (value.includes('tamilnadu')) return 'tamilnadu_marriage';
  if (value.includes('hindu')) return 'hindu_marriage';
  if (value.includes('muslim')) return 'muslim_marriage';
  if (value.includes('christian')) return 'christian_marriage';
  if (value.includes('special')) return 'special_marriage';

  return 'marriage_registration';
}

function replyByLanguage(language, english, tamil, tanglish) {
  const lang = normalizeLanguage(language);
  if (lang === 'Tamil') return tamil;
  if (lang === 'Tanglish') return tanglish;
  return english;
}

function getArray(value) {
  return Array.isArray(value) ? value : [];
}

function getRegistrationOptionEntries(options) {
  if (!options || typeof options !== 'object') return [];

  return Object.entries(options).map(([key, label], index) => ({
    number: String(index + 1),
    key,
    label
  }));
}

function getServiceOptionEntries(services) {
  return getArray(services).map((service, index) => ({
    number: String(index + 1),
    service_id: service.service_id || service.id || '',
    service_name: service.service_name || service.name || '',
    service_code: service.service_code || service.code || toServiceCode(service.service_name || service.name || '')
  }));
}

function isValidOptionNumber(message, entries) {
  return entries.some((item) => item.number === String(message).trim());
}

function getSelectedOption(message, entries) {
  return entries.find((item) => item.number === String(message).trim()) || null;
}

function buildServiceOptionsReply(language, serviceEntries) {
  const lines = serviceEntries.map((item) => `${item.number}. ${item.service_name}`);
  const optionsText = serviceEntries.map(x => x.number).join(', ');

  return replyByLanguage(
    language,
    [
      'Please choose the marriage registration service:',
      '',
      ...lines,
      '',
      `Please reply with ${optionsText}.`
    ].join('\n'),
    [
      'தயவுசெய்து திருமண பதிவு சேவையை தேர்வு செய்யவும்:',
      '',
      ...lines,
      '',
      `தயவுசெய்து ${optionsText} என்று பதிலளிக்கவும்.`
    ].join('\n'),
    [
      'Marriage registration service select pannunga:',
      '',
      ...lines,
      '',
      `${optionsText} la one option reply pannunga.`
    ].join('\n')
  );
}

function buildRegistrationPlaceReply(language, optionEntries) {
  const lines = optionEntries.map((item) => `${item.number}. ${item.label}`);
  const optionsText = optionEntries.map(x => x.number).join(', ');

  return replyByLanguage(
    language,
    [
      'Please choose the place where you want to register the marriage.',
      '',
      ...lines,
      '',
      `Please reply with ${optionsText}.`
    ].join('\n'),
    [
      'திருமணத்தை பதிவு செய்ய வேண்டிய இடத்தை தேர்வு செய்யவும்.',
      '',
      ...lines,
      '',
      `தயவுசெய்து ${optionsText} என்று பதிலளிக்கவும்.`
    ].join('\n'),
    [
      'Marriage register panna place select pannunga.',
      '',
      ...lines,
      '',
      `${optionsText} la one option reply pannunga.`
    ].join('\n')
  );
}

function buildConfirmationReply(language, customer, bride, groom, marriage, serviceLabel) {
  return replyByLanguage(
    language,

    [
      '*Please confirm the details below:*',
      '',
      '👤 *Customer Details*',
      `• Name: ${customer.name}`,
      `• Mobile Number: ${customer.mobile}`,
      '',
      '👰 *Bride Details*',
      `• Name: ${bride.name}`,
      `• Date of Birth: ${bride.dob}`,
      `• Religion: ${bride.religion}`,
      `• Address: ${bride.address}`,
      `• NRI Status: ${bride.is_nri}`,
      '',
      '🤵 *Groom Details*',
      `• Name: ${groom.name}`,
      `• Date of Birth: ${groom.dob}`,
      `• Religion: ${groom.religion}`,
      `• Address: ${groom.address}`,
      `• NRI Status: ${groom.is_nri}`,
      '',
      '💍 *Marriage Details*',
      `• Marriage Date: ${marriage.marriage_date}`,
      `• Place of Marriage: ${marriage.marriage_place}`,
      `• Registration Place: ${marriage.registration_place_label}`,
      `• Selected Service: ${serviceLabel}`,
      '',
      '*Please confirm the above details.*',
      '',
      '1️⃣ Confirm',
      '2️⃣ Correct Details'
    ].join('\n'),

    [
      '*கீழே உள்ள விவரங்களை உறுதிப்படுத்தவும்:*',
      '',
      '👤 *வாடிக்கையாளர் விவரங்கள்*',
      `• பெயர்: ${customer.name}`,
      `• மொபைல் எண்: ${customer.mobile}`,
      '',
      '👰 *மணமகள் விவரங்கள்*',
      `• பெயர்: ${bride.name}`,
      `• பிறந்த தேதி: ${bride.dob}`,
      `• மதம்: ${bride.religion}`,
      `• முகவரி: ${bride.address}`,
      `• NRI நிலை: ${bride.is_nri}`,
      '',
      '🤵 *மணமகன் விவரங்கள்*',
      `• பெயர்: ${groom.name}`,
      `• பிறந்த தேதி: ${groom.dob}`,
      `• மதம்: ${groom.religion}`,
      `• முகவரி: ${groom.address}`,
      `• NRI நிலை: ${groom.is_nri}`,
      '',
      '💍 *திருமண விவரங்கள்*',
      `• திருமண தேதி: ${marriage.marriage_date}`,
      `• திருமண இடம்: ${marriage.marriage_place}`,
      `• பதிவு இடம்: ${marriage.registration_place_label}`,
      `• தேர்வு செய்த சேவை: ${serviceLabel}`,
      '',
      '*மேலுள்ள விவரங்களை உறுதிப்படுத்தவும்.*',
      '',
      '1️⃣ உறுதிப்படுத்தவும்',
      '2️⃣ திருத்தவும்'
    ].join('\n'),

    [
      '*Keela irukkura details confirm pannunga:*',
      '',
      '👤 *Customer Details*',
      `• Name: ${customer.name}`,
      `• Mobile Number: ${customer.mobile}`,
      '',
      '👰 *Bride Details*',
      `• Name: ${bride.name}`,
      `• DOB: ${bride.dob}`,
      `• Religion: ${bride.religion}`,
      `• Address: ${bride.address}`,
      `• NRI Status: ${bride.is_nri}`,
      '',
      '🤵 *Groom Details*',
      `• Name: ${groom.name}`,
      `• DOB: ${groom.dob}`,
      `• Religion: ${groom.religion}`,
      `• Address: ${groom.address}`,
      `• NRI Status: ${groom.is_nri}`,
      '',
      '💍 *Marriage Details*',
      `• Marriage Date: ${marriage.marriage_date}`,
      `• Marriage Place: ${marriage.marriage_place}`,
      `• Registration Place: ${marriage.registration_place_label}`,
      `• Selected Service: ${serviceLabel}`,
      '',
      '*Mela irukkura details confirm pannunga.*',
      '',
      '1️⃣ Confirm',
      '2️⃣ Correct Details'
    ].join('\n')
  );
}

// --------------------------------------------------
// Parse AI output and session data
// --------------------------------------------------

const aiParsed = parseMaybeJson(rawInput.output || rawInput.text || rawInput.reply);

const input = {
  ...aiParsed,
  ...rawInput,
  ...inbound
};

const sessionData = parseMaybeJson(
  input.session_data ||
  inbound.session_data ||
  aiParsed.session_data
);

const nestedSessionData = parseMaybeJson(sessionData.session_data);

// Merge nested session if any accidental nesting happened
const s = {
  ...sessionData,
  ...nestedSessionData
};

const message = String(inbound.message || input.message || '').trim();
const lowerMessage = message.toLowerCase();

const language = normalizeLanguage(pick(input.language, inbound.language, s.language, 'English'));

// --------------------------------------------------
// Normalize all collected data
// Supports both:
// customer.name and customer_details.customer_name
// bride.dob and bride_details.bride_dob
// --------------------------------------------------

const customer = {
  name: pick(
    input.customer?.name,
    input.customer_name,
    input.customer_details?.customer_name,
    s.customer?.name,
    s.customer_details?.customer_name
  ),
  mobile: normalizeMobile(pick(
    input.customer?.mobile,
    input.customer_mobile,
    input.customer_details?.customer_mobile,
    s.customer?.mobile,
    s.customer_details?.customer_mobile
  ))
};

const bride = {
  name: pick(
    input.bride?.name,
    input.bride_name,
    input.bride_details?.bride_name,
    s.bride?.name,
    s.bride_details?.bride_name
  ),
  dob: normalizeDateInput(pick(
    input.bride?.dob,
    input.bride_dob,
    input.bride_details?.bride_dob,
    s.bride?.dob,
    s.bride_details?.bride_dob
  )),
  religion: normalizeReligion(pick(
    input.bride?.religion,
    input.bride_religion,
    input.bride_details?.bride_religion,
    s.bride?.religion,
    s.bride_details?.bride_religion
  )),
  address: pick(
    input.bride?.address,
    input.bride_address,
    input.bride_details?.bride_address,
    s.bride?.address,
    s.bride_details?.bride_address
  ),
  is_nri: pick(
    input.bride?.is_nri,
    input.bride_is_nri,
    input.bride_details?.bride_is_nri,
    input.bride_details?.is_nri,
    s.bride?.is_nri,
    s.bride_details?.bride_is_nri,
    s.bride_details?.is_nri
  )
};

const groom = {
  name: pick(
    input.groom?.name,
    input.groom_name,
    input.groom_details?.groom_name,
    s.groom?.name,
    s.groom_details?.groom_name
  ),
  dob: normalizeDateInput(pick(
    input.groom?.dob,
    input.groom_dob,
    input.groom_details?.groom_dob,
    s.groom?.dob,
    s.groom_details?.groom_dob
  )),
  religion: normalizeReligion(pick(
    input.groom?.religion,
    input.groom_religion,
    input.groom_details?.groom_religion,
    s.groom?.religion,
    s.groom_details?.groom_religion
  )),
  address: pick(
    input.groom?.address,
    input.groom_address,
    input.groom_details?.groom_address,
    s.groom?.address,
    s.groom_details?.groom_address
  ),
  is_nri: pick(
    input.groom?.is_nri,
    input.groom_is_nri,
    input.groom_details?.groom_is_nri,
    input.groom_details?.is_nri,
    s.groom?.is_nri,
    s.groom_details?.groom_is_nri,
    s.groom_details?.is_nri
  )
};

const marriage = {
  marriage_date: normalizeDateInput(pick(
    input.marriage?.marriage_date,
    input.marriage_date,
    input.marriage_details?.marriage_date,
    s.marriage?.marriage_date,
    s.marriage_details?.marriage_date
  )),
  marriage_place: pick(
    input.marriage?.marriage_place,
    input.marriage_place,
    input.marriage_details?.marriage_place,
    s.marriage?.marriage_place,
    s.marriage_details?.marriage_place
  ),
  registration_place_option: pick(
    input.marriage?.registration_place_option,
    input.registration_place_option,
    input.marriage_registration_place_option,
    input.marriage_details?.registration_place_option,
    input.marriage_details?.marriage_registration_place_option,
    s.marriage?.registration_place_option,
    s.registration_place_option,
    s.marriage_details?.registration_place_option,
    s.marriage_details?.marriage_registration_place_option
  ),
  registration_place_label: pick(
    input.marriage?.registration_place_label,
    input.registration_place_label,
    input.marriage_registration_place_label,
    input.marriage_details?.registration_place_label,
    input.marriage_details?.marriage_registration_place_label,
    s.marriage?.registration_place_label,
    s.registration_place_label,
    s.marriage_details?.registration_place_label,
    s.marriage_details?.marriage_registration_place_label
  )
};

const brideAge = calculateAge(bride.dob);
const groomAge = calculateAge(groom.dob);
const serviceCategory = getServiceCategory(bride.religion, groom.religion);
const serviceCost = getServiceCost(marriage.marriage_date);

let selectedServiceOption = pick(
  input.selected_service_option,
  input.service_details?.selected_service_option,
  s.selected_service_option,
  s.service_details?.selected_service_option
);

// Old behavior preserved only before new Odoo options are fetched.
// After Odoo options are fetched, selected service may be Muslim/Christian/Special also.
if (
  serviceCategory !== 'Hindu Marriage' &&
  toBool(input.marriage_options_fetched) !== true &&
  toBool(s.marriage_options_fetched) !== true
) {
  selectedServiceOption = '';
}

let calculatedServiceName = pick(
  input.calculated_service_name,
  input.service_details?.calculated_service_name,
  s.calculated_service_name,
  s.service_details?.calculated_service_name,
  `${serviceCategory} LANDOC Service`
);

let calculatedServiceCost = pick(
  input.calculated_service_cost,
  input.service_details?.calculated_service_cost,
  s.calculated_service_cost,
  s.service_details?.calculated_service_cost,
  serviceCost.formatted
);

// --------------------------------------------------
// Build base result
// --------------------------------------------------

let currentStage = pick(
  inbound.current_stage,
  s.current_stage,
  input.current_stage,
  'start'
);

let reply = pick(
  input.reply,
  input.output,
  input.chatbot_reply,
  input.last_reply,
  ''
);

let result = {
  ...input,

  output: reply,
  reply,
  chatbot_reply: reply,
  last_reply: reply,

  active_service: 'marriage_registration',
  source: input.source || 'odoo_chatbot',
  status: input.status || '',
  language,

  current_stage: currentStage,

  main_menu_selected: input.main_menu_selected || '',
  intent: input.intent || '',

  service_category: serviceCategory,
  service_name: serviceCategory,
  selected_service_option: selectedServiceOption,
  selected_service_option_backend: pick(
    input.selected_service_option_backend,
    input.service_details?.selected_service_option_backend,
    s.selected_service_option_backend,
    s.service_details?.selected_service_option_backend,
    selectedServiceOption
  ),
  selected_service_option_label: pick(
    input.selected_service_option_label,
    input.service_details?.selected_service_option_label,
    s.selected_service_option_label,
    s.service_details?.selected_service_option_label,
    selectedServiceOption
  ),
  selected_service_id: pick(
    input.selected_service_id,
    input.service_details?.selected_service_id,
    s.selected_service_id,
    s.service_details?.selected_service_id
  ),

  selected_cost: serviceCost.cost,
  cost_shown: toBool(input.cost_shown) || toBool(s.cost_shown) || toBool(s.confirmation_details?.cost_shown),

  calculated_service_name: calculatedServiceName,
  calculated_service_cost: calculatedServiceCost,

  marriage_options_fetched: toBool(input.marriage_options_fetched) || toBool(s.marriage_options_fetched),
  need_marriage_options: false,

  bride_religion_for_options: normalizeReligionForOptions(bride.religion),
  groom_religion_for_options: normalizeReligionForOptions(groom.religion),
  marriage_date_for_options: normalizeMarriageDateForApi(marriage.marriage_date),

  available_marriage_services: input.available_marriage_services || s.available_marriage_services || [],
  registration_place_options: input.registration_place_options || s.registration_place_options || {},

  ticket_status_requested: false,
  ticket_reference: '',
  ticket_mobile: '',
  ready_to_fetch_ticket_status: false,

  customer_confirmed: toBool(input.customer_confirmed) || toBool(s.customer_confirmed) || toBool(s.confirmation_details?.customer_confirmed),
  correction_requested: toBool(input.correction_requested) || toBool(s.correction_requested) || toBool(s.confirmation_details?.correction_requested),

  hindu_option_required: serviceCategory === 'Hindu Marriage' && !selectedServiceOption,
  hindu_option_selected: serviceCategory === 'Hindu Marriage' && !!selectedServiceOption,

  proceed_confirmed: toBool(input.proceed_confirmed) || toBool(s.proceed_confirmed) || toBool(s.confirmation_details?.proceed_confirmed),

  not_interested: toBool(input.not_interested) || toBool(s.not_interested),
  not_interested_reason: pick(input.not_interested_reason, s.not_interested_reason),

  customer,
  bride,
  groom,
  marriage,

  ready_to_create_lead: toBool(input.ready_to_create_lead),
  lead_creation_required: toBool(input.lead_creation_required),
  lead_created: toBool(input.lead_created) || toBool(s.lead_created) || toBool(s.lead_details?.lead_created),
  lead_creation_status: input.lead_creation_status || '',
  odoo_lead_id: pick(input.odoo_lead_id, s.odoo_lead_id, s.lead_details?.odoo_lead_id),
  odoo_ticket_reference: input.odoo_ticket_reference || '',
  lead_payload_ready: toBool(input.lead_payload_ready),

  payment_required: toBool(input.payment_required) || toBool(s.payment_required) || toBool(s.payment_details?.payment_required),
  payment_stage: pick(input.payment_stage, s.payment_stage, s.payment_details?.payment_stage),
  payment_status: pick(input.payment_status, s.payment_status, s.payment_details?.payment_status),
  advance_percentage_requested: pick(input.advance_percentage_requested, s.advance_percentage_requested, s.payment_details?.advance_percentage_requested),
  advance_amount_requested: pick(input.advance_amount_requested, s.advance_amount_requested, s.payment_details?.advance_amount_requested),
  amount_paid: pick(input.amount_paid, s.amount_paid, s.payment_details?.amount_paid),
  payment_screenshot_received: toBool(input.payment_screenshot_received) || toBool(s.payment_screenshot_received) || toBool(s.payment_details?.payment_screenshot_received),
  payment_screenshot_url: pick(input.payment_screenshot_url, s.payment_screenshot_url, s.payment_details?.payment_screenshot_url),
  payment_pending_amount: pick(input.payment_pending_amount, s.payment_pending_amount, s.payment_details?.payment_pending_amount),
  customer_refused_payment: toBool(input.customer_refused_payment) || toBool(s.customer_refused_payment) || toBool(s.payment_details?.customer_refused_payment),
  payment_note: pick(input.payment_note, s.payment_note, s.payment_details?.payment_note),

  documents_status: pick(input.documents_status, s.documents_status, s.document_details?.documents_status),
  documents_collected: toBool(input.documents_collected) || toBool(s.documents_collected) || toBool(s.document_details?.documents_collected),
  additional_documents_required: toBool(input.additional_documents_required) || toBool(s.additional_documents_required) || toBool(s.document_details?.additional_documents_required),
  additional_document_list: input.additional_document_list || s.additional_document_list || s.document_details?.additional_document_list || [],

  close_session: toBool(input.close_session)
};

