// --------------------------------------------------
// Stage decisions
// --------------------------------------------------

const stage = currentStage;

// --------------------------------------------------
// Direct stage capture fixes
// --------------------------------------------------
// When the customer is in collect_marriage_place stage,
// the user's message itself is the marriage place.
// This is required before triggering the new Odoo marriage options API.

if (
  stage === 'collect_marriage_place' &&
  message &&
  !marriage.marriage_place
) {
  marriage.marriage_place = message;

  result.marriage = marriage;

  result.marriage_details = {
    ...(result.marriage_details || {}),
    marriage_date: marriage.marriage_date,
    marriage_place: marriage.marriage_place,
    registration_place_option: marriage.registration_place_option,
    registration_place_label: marriage.registration_place_label
  };
}

const isCostConfirmationStage = [
  'cost_confirmation',
  'cost_confirmation_pending'
].includes(stage);

// New: Need Odoo marriage registration options after core details are collected
if (
  bride.religion &&
  groom.religion &&
  marriage.marriage_date &&
  marriage.marriage_place &&
  result.marriage_options_fetched !== true &&
  ![
    'marriage_options_pending',
    'service_option_pending',
    'registration_place_option_pending',
    'details_confirmation_pending',
    'cost_confirmation',
    'cost_confirmation_pending',
    'lead_creation_pending',
    'payment_collection',
    'payment_screenshot_pending',
    'documents_collection'
  ].includes(stage)
) {
  result.current_stage = 'marriage_options_pending';
  result.need_marriage_options = true;
  result.need_odoo_fee = false;
  result.ready_to_create_lead = false;
  result.lead_creation_required = false;
  result.lead_payload_ready = false;

  reply = replyByLanguage(
    language,
    'Please wait while we fetch the eligible marriage registration options.',
    'தகுதியான திருமண பதிவு விருப்பங்களை பெறுகிறோம். தயவுசெய்து காத்திருக்கவும்.',
    'Eligible marriage registration options fetch panrom. Konjam wait pannunga.'
  );
}

// Service option selection from Odoo API
else if (stage === 'service_option_pending') {
  const serviceEntries = getServiceOptionEntries(s.available_marriage_services || result.available_marriage_services);

  if (!serviceEntries.length) {
    result.current_stage = 'marriage_options_pending';
    result.need_marriage_options = true;
    result.need_odoo_fee = false;

    reply = replyByLanguage(
      language,
      'Please wait while we fetch the eligible marriage registration options again.',
      'தகுதியான திருமண பதிவு விருப்பங்களை மீண்டும் பெறுகிறோம். தயவுசெய்து காத்திருக்கவும்.',
      'Eligible marriage options again fetch panrom. Konjam wait pannunga.'
    );
  } else if (!isValidOptionNumber(message, serviceEntries)) {
    result.current_stage = 'service_option_pending';
    result.need_marriage_options = false;
    result.need_odoo_fee = false;

    reply = replyByLanguage(
      language,
      `Please reply with a valid service option: ${serviceEntries.map(x => x.number).join(', ')}.`,
      `சரியான சேவை விருப்ப எண்ணை பதிலளிக்கவும்: ${serviceEntries.map(x => x.number).join(', ')}.`,
      `Correct service option number reply pannunga: ${serviceEntries.map(x => x.number).join(', ')}.`
    );
  } else {
    const selected = getSelectedOption(message, serviceEntries);
    const registrationEntries = getRegistrationOptionEntries(s.registration_place_options || result.registration_place_options);

    result.selected_service_id = selected.service_id;
    result.selected_service_option = selected.service_name;
    result.selected_service_option_backend = selected.service_code;
    result.selected_service_option_label = selected.service_name;
    result.service_code = selected.service_code;
    result.service_code_for_fee = selected.service_code;

    result.hindu_option_required = false;
    result.hindu_option_selected = true;

    result.current_stage = 'registration_place_option_pending';
    result.need_marriage_options = false;
    result.need_odoo_fee = false;

    reply = buildRegistrationPlaceReply(language, registrationEntries);
  }
}

// Registration place selection from Odoo API
else if (stage === 'registration_place_option_pending') {
  const registrationEntries = getRegistrationOptionEntries(s.registration_place_options || result.registration_place_options);

  if (!registrationEntries.length) {
    result.current_stage = 'marriage_options_pending';
    result.need_marriage_options = true;
    result.need_odoo_fee = false;

    reply = replyByLanguage(
      language,
      'Please wait while we fetch the eligible registration place options again.',
      'தகுதியான பதிவு இட விருப்பங்களை மீண்டும் பெறுகிறோம். தயவுசெய்து காத்திருக்கவும்.',
      'Registration place options again fetch panrom. Konjam wait pannunga.'
    );
  } else if (!isValidOptionNumber(message, registrationEntries)) {
    result.current_stage = 'registration_place_option_pending';
    result.need_marriage_options = false;
    result.need_odoo_fee = false;

    reply = replyByLanguage(
      language,
      `Please reply with a valid registration place option: ${registrationEntries.map(x => x.number).join(', ')}.`,
      `சரியான பதிவு இட விருப்ப எண்ணை பதிலளிக்கவும்: ${registrationEntries.map(x => x.number).join(', ')}.`,
      `Correct registration place option number reply pannunga: ${registrationEntries.map(x => x.number).join(', ')}.`
    );
  } else {
    const selectedPlace = getSelectedOption(message, registrationEntries);

    marriage.registration_place_option = selectedPlace.key;
    marriage.registration_place_label = selectedPlace.label;

    result.marriage = marriage;
    result.current_stage = 'details_confirmation_pending';
    result.need_marriage_options = false;
    result.need_odoo_fee = false;

    const serviceLabel =
      result.selected_service_option_label ||
      s.selected_service_option_label ||
      s.service_details?.selected_service_option_label ||
      result.service_category;

    reply = buildConfirmationReply(
      language,
      customer,
      bride,
      groom,
      marriage,
      serviceLabel
    );
  }
}

// Details confirmed
else if (stage === 'details_confirmation_pending' && message === '1') {
  result.customer_confirmed = true;
  result.correction_requested = false;
  result.proceed_confirmed = false;
  result.ready_to_create_lead = false;
  result.lead_creation_required = false;
  result.lead_payload_ready = false;

  if (
    serviceCategory === 'Hindu Marriage' &&
    !selectedServiceOption &&
    result.marriage_options_fetched !== true
