  function safeString(value) {
    return String(value || '').trim();
  }

  function parseSessionData(value) {
    if (!value) return {};
    if (typeof value === 'object') return value;

    try {
      return JSON.parse(value);
    } catch (error) {
      return {};
    }
  }

  function isValidMobile(value) {
    return /^[6-9]\d{9}$/.test(safeString(value));
  }

  function isValidDate(value) {
    return /^\d{2}\/\d{2}\/\d{4}$/.test(safeString(value));
  }

  function religionFromInput(value) {
    const v = safeString(value).toLowerCase();

    if (v === '1' || v.includes('hindu')) return 'Hindu';
    if (v === '2' || v.includes('muslim')) return 'Muslim';
    if (v === '3' || v.includes('christian')) return 'Christian';
    if (v === '4' || v.includes('other')) return 'Other';

    return '';
  }

  function nriFromInput(value) {
    const v = safeString(value).toLowerCase();

    if (v === '1' || v === 'yes' || v === 'y' || v.includes('nri')) {
      if (v.includes('not nri') || v.includes('non nri') || v.includes('no nri')) {
        return 'no';
      }
      return 'yes';
    }

    if (v === '2' || v === 'no' || v === 'n') return 'no';

    return '';
  }

  function registrationPlaceFromInput(value) {
    const v = safeString(value).toLowerCase();

    if (v === '1' || v.includes('bride')) {
      return {
        option: 'bride_residence',
        label: 'Residence of the Bride'
      };
    }

    if (v === '2' || v.includes('groom') || v.includes('bridegroom')) {
      return {
        option: 'groom_residence',
        label: 'Residence of the Groom'
      };
    }

    if (
      v === '3' ||
      v.includes('marriage place') ||
      v.includes('solemnized') ||
      v.includes('marriage nadandha')
    ) {
      return {
        option: 'marriage_place',
        label: 'Place where the marriage was solemnized'
      };
    }

    return {
      option: '',
      label: ''
    };
  }

  function parseDateDDMMYYYY(value) {
    const [dd, mm, yyyy] = safeString(value).split('/').map(Number);
    return new Date(yyyy, mm - 1, dd);
  }

  function calculateAge(dob) {
    if (!isValidDate(dob)) return '';
    const birthDate = parseDateDDMMYYYY(dob);
    const today = new Date();

    let age = today.getFullYear() - birthDate.getFullYear();
    const monthDiff = today.getMonth() - birthDate.getMonth();

    if (
      monthDiff < 0 ||
      (monthDiff === 0 && today.getDate() < birthDate.getDate())
    ) {
      age--;
    }

    return age;
  }

  function calculateMarriageDays(marriageDate) {
    if (!isValidDate(marriageDate)) return '';

    const marriage = parseDateDDMMYYYY(marriageDate);
    const today = new Date();

    return Math.floor((today.getTime() - marriage.getTime()) / (1000 * 60 * 60 * 24));
  }

  function getServiceCategory(brideReligion, groomReligion) {
    if (brideReligion === 'Hindu' && groomReligion === 'Hindu') {
      return 'Hindu Marriage';
    }

    if (brideReligion === 'Muslim' && groomReligion === 'Muslim') {
      return 'Muslim Marriage';
    }

    if (brideReligion === 'Christian' && groomReligion === 'Christian') {
      return 'Christian Marriage';
    }

    if (brideReligion && groomReligion && brideReligion !== groomReligion) {
      return 'Special Marriage';
    }

    return 'Need Team Verification';
  }

  function getCost(marriageDate) {
    const days = calculateMarriageDays(marriageDate);

    if (days !== '' && days > 150) {
      return 7500;
    }

    return 6000;
  }

  function formatCost(amount) {
