      }
    }
  ];
}

const input = $input.first().json || {};

function parseSession(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;

  try {
    return JSON.parse(raw);
  } catch (e) {
    return {};
  }
}

function toAmount(value) {
  if (value === null || value === undefined || value === '') return 0;
  return Number(String(value).replace(/[₹,\s]/g, '')) || 0;
}

function formatAmount(value) {
  const amount = toAmount(value);
  if (!amount) return '0';
  return String(amount);
}

function normalizeLang(lang) {
  const value = String(lang || '').trim().toLowerCase();
  if (value.includes('tamil') || value === 'ta' || value === 'தமிழ்') return 'tamil';
  if (value.includes('tanglish')) return 'tanglish';
  return 'english';
}

function hasAttachment(input) {
  const attachmentInfo = String(input.attachment_info || '').trim();
  const binaryKey = String(input.attachment_binary_key || '').trim();
  const base64 = String(input.attachment_base64 || '').trim();

  return (
    input.has_attachment === true ||
    input.has_attachment === 'true' ||
    Number(input.attachment_count || 0) > 0 ||
    input.attachment_base64_available === true ||
    input.attachment_base64_available === 'true' ||
    base64 !== '' ||
    (attachmentInfo !== '' && attachmentInfo !== '||') ||
    (binaryKey !== '' && binaryKey !== 'undefined' && binaryKey !== 'null')
  );
}

function getDocCode(doc) {
  return doc?.description_code || doc?.code || doc?.document_code || '';
}

function getDocLabel(doc) {
  return (
    doc?.label ||
    doc?.name ||
    doc?.description ||
    doc?.document_name ||
    getDocCode(doc) ||
    'the document'
  );
}

function isUploadRequired(doc) {
  if (!doc || typeof doc !== 'object') return false;

  if (doc.is_attachment_required !== undefined) {
    return (
      doc.is_attachment_required === true ||
      doc.is_attachment_required === 'true' ||
      doc.is_attachment_required === 1 ||
      doc.is_attachment_required === '1'
    );
  }

  if (doc.attachment_required !== undefined) {
    return (
      doc.attachment_required === true ||
      doc.attachment_required === 'true' ||
      doc.attachment_required === 1 ||
      doc.attachment_required === '1'
    );
  }

  if (doc.required !== undefined) {
    return (
      doc.required === true ||
      doc.required === 'true' ||
      doc.required === 1 ||
      doc.required === '1'
    );
  }

  return false;
}

function isUploadedOrBackendDone(doc) {
  const status = String(doc?.bot_status || doc?.status || '').toLowerCase();

  return (
    doc?.uploaded === true ||
    doc?.uploaded === 'true' ||
    status === 'uploaded' ||
    status === 'approved' ||
    status === 'correction_uploaded'
  );
}

function isRejected(doc) {
  const status = String(doc?.bot_status || doc?.status || '').toLowerCase();
  return status === 'rejected';
}

function getAllDocs(data) {
  if (Array.isArray(data.document_checklist) && data.document_checklist.length) {
    return data.document_checklist;
  }

  if (Array.isArray(data.required_documents) && data.required_documents.length) {
    return data.required_documents;
  }

  return [];
}

function updateDocInSession(data, code, updateValues) {
  function updateList(list) {
    if (!Array.isArray(list)) return list;

    return list.map((doc) => {
      if (getDocCode(doc) === code) {
        return {
          ...doc,
          ...updateValues
        };
      }
      return doc;
    });
  }

  data.document_checklist = updateList(data.document_checklist);
  data.required_documents = updateList(data.required_documents);
  data.pending_required_documents = updateList(data.pending_required_documents);
}

function getNextPendingNormalDoc(data) {
  const docs = getAllDocs(data);

  return docs.find(doc =>
    isUploadRequired(doc) &&
    !isUploadedOrBackendDone(doc) &&
    !isRejected(doc) &&
    doc.upload_later !== true &&
    doc.upload_later !== 'true'
  );
}

function getNextUploadLaterDoc(data) {
  const docs = getAllDocs(data);

  return docs.find(doc =>
    isUploadRequired(doc) &&
    !isUploadedOrBackendDone(doc) &&
    !isRejected(doc) &&
    (
      doc.upload_later === true ||
      doc.upload_later === 'true'
    )
  );
}

function getAllUploadLaterDocs(data) {
  const docs = getAllDocs(data);

  return docs.filter(doc =>
    isUploadRequired(doc) &&
    !isUploadedOrBackendDone(doc) &&
    !isRejected(doc) &&
    (
      doc.upload_later === true ||
      doc.upload_later === 'true'
    )
  );
}

