function buildSkippedDocumentsMessage(data, lang) {
  const skippedDocs = getAllUploadLaterDocs(data);

  if (!skippedDocs.length) {
    if (lang === 'tamil') {
      return (
        `தேவையான அனைத்து ஆவணங்களும் பெறப்பட்டுள்ளன.\n\n` +
        `ஆவண சரிபார்ப்பு நிலையை அறிய 1 என்று பதிலளிக்கவும்.`
      );
    }

    if (lang === 'tanglish') {
      return (
        `Required documents ellam receive pannitom.\n\n` +
        `Document verification status check panna 1 reply pannunga.`
      );
    }

    return (
      `All required documents have been received.\n\n` +
      `Reply 1 to check your document verification status.`
    );
  }

  const lines = skippedDocs
    .map((doc, index) => `${index + 1}. ${getDocLabel(doc)}`)
    .join('\n');

  if (lang === 'tamil') {
    return (
      `கீழே உள்ள தேவையான ஆவணங்கள் இன்னும் பதிவேற்றப்படவில்லை:\n\n` +
      `${lines}\n\n` +
      `இந்த ஆவணங்கள் தயார் ஆன பிறகு, பதிவேற்றத்தை தொடர 1 என்று பதிலளிக்கவும்.`
    );
  }

  if (lang === 'tanglish') {
    return (
      `Innum upload panna vendiya required documents:\n\n` +
      `${lines}\n\n` +
      `Indha documents ready ah irundha, continue panna 1 reply pannunga.`
    );
  }

  return (
    `The following required documents are still pending:\n\n` +
    `${lines}\n\n` +
    `When these documents are ready, reply 1 to continue uploading the pending documents.`
  );
}

function getPaymentAmounts(data) {
  const paidAmount = toAmount(
    data.paid_amount ||
    data.amount_paid ||
    data.payment_details?.amount_paid ||
    0
  );

  const totalAmount = toAmount(
    data.total_amount ||
    data.quotation_amount ||
    data.selected_service_cost ||
    data.calculated_service_cost ||
    data.service_details?.calculated_service_cost ||
    0
  );

  let pendingAmount = toAmount(
    data.payment_pending_amount ||
    data.payment_details?.payment_pending_amount ||
    0
  );

  if (pendingAmount <= 0 && totalAmount > 0) {
    pendingAmount = Math.max(totalAmount - paidAmount, 0);
  }

  return {
    paidAmount,
    totalAmount,
    pendingAmount
  };
}

function getAvailableServiceDates(data) {
  if (Array.isArray(data.available_service_dates)) return data.available_service_dates;
  if (Array.isArray(data.service_available_dates)) return data.service_available_dates;
  if (Array.isArray(data.available_dates)) return data.available_dates;
  return [];
}

function getDateOption(item, index) {
  return String(item?.option || item?.number || index + 1);
}

function getDateValue(item) {
  return (
    item?.date ||
    item?.available_date ||
    item?.selected_date ||
    item?.service_date ||
    ''
  );
}

function getDisplayDate(item) {
  return (
    item?.display_date ||
    item?.date ||
    item?.available_date ||
    item?.selected_date ||
    item?.service_date ||
    ''
  );
}

let data = parseSession(input.session_data);

const msg = String(
  input.message ||
  input.text ||
  input.body ||
  input.incoming_message ||
  ''
).trim();

const lower = msg.toLowerCase();

let stage = String(
  data.current_stage ||
  input.current_stage ||
  ''
).trim();

const availableServiceDates = getAvailableServiceDates(data);

/**
 * CRITICAL ROUTING FIX:
 * Once available registration dates are already shown,
 * the next numeric reply must be treated as date selection.
 *
 * This prevents repeated date fetching and prevents going back to documents_verified.
 */
if (
  availableServiceDates.length > 0 &&
  (
    data.current_stage === 'service_date_selection' ||
    input.current_stage === 'service_date_selection' ||
    stage === 'service_date_fetch' ||
    stage === 'documents_verified'
  )
) {
  stage = 'service_date_selection';
}

const language = input.language || data.language || 'English';
const lang = normalizeLang(language);

const paymentDocumentStages = [
  'waiting_for_payment_confirmation',
  'fetch_document_checklist',
  'document_checklist_ready',
  'document_collection',
  'document_pending_uploads',
  'document_verification_pending',
  'documents_collection',
  'documents_pending_verification',
  'document_correction_collection',
  'documents_verified',
  'service_date_fetch',
  'service_date_selection',
  'service_date_confirmed'
];


const postLeadStageAliases = [
  'waiting_for_payment_confirmation',
  'fetch_document_checklist',
  'document_checklist_ready',
  'document_collection',
  'documents_collection',
  'document_pending_uploads',
  'document_verification_pending',
  'documents_pending_verification',
  'document_correction_collection',
  'documents_verified',
  'service_date_fetch',
  'service_date_selection',
  'service_date_confirmed'
];

const sessionLooksPostLead =
  data.payment_status ||
  data.quotation_id ||
  data.quotation_preview_url ||
  data.payment_link ||
  data.document_checklist ||
  data.required_documents ||
  data.documents_status ||
  data.document_verification_status ||
  data.available_service_dates ||
  data.current_document_code ||
  data.current_correction_document_code ||
  data.odoo_lead_id ||
  data.lead_id ||
  data.odoo_request_number ||
  data.request_number;

/**
 * POST-LEAD STAGE NORMALIZATION
 *
 * This runs before the normal stage gate.
 * It prevents post-lead messages from escaping to AI Agent when top-level
 * current_stage is stale or session_data contains the actual post-lead state.
 */
if (!paymentDocumentStages.includes(stage) && sessionLooksPostLead) {
  if (availableServiceDates.length > 0) {
    stage = 'service_date_selection';
  } else if (
    data.documents_verified === true ||
    data.documents_verified === 'true' ||
    data.document_verification_status === 'verified'
  ) {
    stage = 'documents_verified';
  } else if (
    data.document_correction_required === true ||
    data.correction_required === true ||
    data.documents_status === 'correction_required' ||
    Array.isArray(data.correction_queue)
  ) {
    stage = 'document_correction_collection';
  } else if (
    data.awaiting_document_status_check === true ||
    data.documents_status === 'pending_verification' ||
    data.document_verification_status === 'pending_verification' ||
    data.document_collection_completed === true
  ) {
    stage = 'document_verification_pending';
  } else if (postLeadStageAliases.includes(String(data.current_stage || '').trim())) {
    stage = String(data.current_stage || '').trim();
  } else {
    stage = 'document_verification_pending';
  }
}

if (!paymentDocumentStages.includes(stage)) {
  return [
    {
      json: {
        ...input,
        payment_document_handled: false,
        need_document_checklist: false,
        need_document_upload_to_odoo: false,
        is_correction_upload: false,
        need_service_date_fetch: false,
        need_service_date_save: false,
        close_session: false,
        session_data: JSON.stringify(data)
      }
    }
  ];
}

/**
 * PAYMENT CHECK STAGE
 */
if (stage === 'waiting_for_payment_confirmation') {
  const totalAmount = toAmount(
    data.total_amount ||
    data.quotation_amount ||
    data.selected_service_cost ||
    data.calculated_service_cost ||
    0
  );

  const paidAmount = toAmount(
    data.paid_amount ||
    data.amount_paid ||
    0
  );

  const remainingAmount = toAmount(
    data.payment_pending_amount ||
    Math.max(totalAmount - paidAmount, 0)
  );

  const paymentStatus = String(data.payment_status || 'pending').toLowerCase();

  const paymentLink =
    data.quotation_preview_url ||
    data.payment_link ||
    data.portal_payment_url ||
    '';

  if (msg !== '1') {
    const reply = [
      'Please complete the payment using the quotation link shared above.',
      '',
      paymentLink || '',
      '',
      'After payment, reply 1 to check your payment status.'
    ].filter(Boolean).join('\n');

    data.current_stage = 'waiting_for_payment_confirmation';
    data.need_document_checklist = false;
    data.can_collect_documents = false;
    data.last_reply = reply;

    return [{
      json: {
        ...input,
        payment_document_handled: true,
        current_stage: 'waiting_for_payment_confirmation',
        need_document_checklist: false,
        need_document_upload_to_odoo: false,
        is_correction_upload: false,
        need_service_date_fetch: false,
        need_service_date_save: false,
        can_collect_documents: false,
        reply,
        output: reply,
        last_reply: reply,
        session_data: JSON.stringify(data),
        close_session: false
      }
    }];
  }

  const isPaid =
    paymentStatus === 'paid' ||
    paymentStatus === 'fully_paid' ||
    (totalAmount > 0 && paidAmount >= totalAmount);

  const isPartialPaid =
    paymentStatus === 'partial_paid' ||
    paidAmount > 0;

  if (isPaid) {
    const reply = data.payment_status_reply || data.payment_summary_message || [
      'Payment confirmed successfully. Thank you.',
      '',
      `Total amount: ₹${formatAmount(totalAmount)}`,
      `Paid amount: ₹${formatAmount(paidAmount)}`,
      'Remaining amount: ₹0',
      '',
      'We will now continue with document collection.'
    ].join('\n');

    data.payment_status = 'paid';
    data.can_collect_documents = true;
    data.can_deliver_final_documents = true;
    data.need_document_checklist = true;
    data.current_stage = 'fetch_document_checklist';
    data.payment_status_reply = reply;
    data.payment_summary_message = reply;
    data.last_reply = reply;

    return [{
      json: {
        ...input,
        payment_document_handled: true,
        current_stage: 'fetch_document_checklist',
        payment_status: 'paid',
        paid_amount: paidAmount,
        total_amount: totalAmount,
        payment_pending_amount: 0,
        can_collect_documents: true,
        can_deliver_final_documents: true,
        need_document_checklist: true,
        need_document_upload_to_odoo: false,
        is_correction_upload: false,
        need_service_date_fetch: false,
        need_service_date_save: false,
        payment_status_reply: reply,
        reply,
        output: reply,
        last_reply: reply,
        session_data: JSON.stringify(data),
        close_session: false
      }
    }];
  }

  if (isPartialPaid) {
    const reply = data.payment_status_reply || data.payment_summary_message || [
      'Partial payment received successfully. Thank you.',
      '',
      `Total amount: ₹${formatAmount(totalAmount)}`,
      `Paid amount: ₹${formatAmount(paidAmount)}`,
      `Remaining amount: ₹${formatAmount(remainingAmount)}`,
      '',
      'Note: The remaining amount must be paid before final document delivery.',
      '',
      'We will now continue with document collection.'
    ].join('\n');

    data.payment_status = 'partial_paid';
    data.can_collect_documents = true;
    data.can_deliver_final_documents = false;
    data.need_document_checklist = true;
    data.current_stage = 'fetch_document_checklist';
    data.payment_pending_amount = remainingAmount;
    data.payment_status_reply = reply;
    data.payment_summary_message = reply;
    data.last_reply = reply;

    return [{
      json: {
        ...input,
        payment_document_handled: true,
        current_stage: 'fetch_document_checklist',
        payment_status: 'partial_paid',
        paid_amount: paidAmount,
        total_amount: totalAmount,
        payment_pending_amount: remainingAmount,
        can_collect_documents: true,
        can_deliver_final_documents: false,
        need_document_checklist: true,
        need_document_upload_to_odoo: false,
        is_correction_upload: false,
        need_service_date_fetch: false,
        need_service_date_save: false,
        payment_status_reply: reply,
        reply,
        output: reply,
        last_reply: reply,
        session_data: JSON.stringify(data),
        close_session: false
      }
    }];
  }

  const reply = [
    'Payment is still pending or payment was not successful.',
    '',
    `Total amount: ₹${formatAmount(totalAmount)}`,
    'Paid amount: ₹0',
    `Remaining amount: ₹${formatAmount(totalAmount)}`,
    '',
    'Please complete the payment using the quotation link below:',
    '',
    paymentLink || 'Payment link is not available. Our team will share the payment link shortly.',
    '',
    'After payment, reply 1 to check your payment status.'
  ].join('\n');

  data.payment_status = 'pending';
  data.can_collect_documents = false;
  data.can_deliver_final_documents = false;
  data.need_document_checklist = false;
  data.current_stage = 'waiting_for_payment_confirmation';
  data.paid_amount = 0;
  data.payment_pending_amount = totalAmount;
  data.payment_status_reply = reply;
  data.payment_summary_message = reply;
  data.last_reply = reply;

  return [{
    json: {
      ...input,
      payment_document_handled: true,
      current_stage: 'waiting_for_payment_confirmation',
      payment_status: 'pending',
      paid_amount: 0,
      total_amount: totalAmount,
      payment_pending_amount: totalAmount,
      can_collect_documents: false,
      can_deliver_final_documents: false,
      need_document_checklist: false,
      need_document_upload_to_odoo: false,
      is_correction_upload: false,
      need_service_date_fetch: false,
      need_service_date_save: false,
      payment_status_reply: reply,
      reply,
      output: reply,
      last_reply: reply,
      session_data: JSON.stringify(data),
      close_session: false
    }
  }];
}

/**
 * FETCH CHECKLIST
 */
if (stage === 'fetch_document_checklist') {
  data.documents_status = 'ready_to_fetch_checklist';
  data.current_stage = 'fetch_document_checklist';

  const reply = data.payment_summary_message || data.payment_status_reply || 'Please wait while we fetch the required document checklist.';

  return [
    {
      json: {
        ...input,
        output: reply,
        reply,
        last_reply: reply,
        active_service: 'marriage_registration',
        current_stage: 'fetch_document_checklist',
        language,
        session_data: JSON.stringify(data),
        payment_document_handled: true,
        need_document_checklist: true,
        need_document_upload_to_odoo: false,
        is_correction_upload: false,
        need_service_date_fetch: false,
        need_service_date_save: false,
        close_session: false
      }
    }
  ];
}

/**
 * CHECKLIST READY
 */
if (stage === 'document_checklist_ready') {
  if (msg === '1') {
    const firstDoc = getNextPendingNormalDoc(data) || getNextUploadLaterDoc(data);

    if (!firstDoc) {
      const reply = buildSkippedDocumentsMessage(data, lang);

      data.current_stage = 'document_verification_pending';
      data.awaiting_document_upload_start = false;
      data.document_collection_started = false;
      data.document_collection_completed = true;
      data.awaiting_document_status_check = true;
      data.last_reply = reply;

      return [{
        json: {
          ...input,
          output: reply,
          reply,
          last_reply: reply,
          current_stage: 'document_verification_pending',
          language,
          session_data: JSON.stringify(data),
          payment_document_handled: true,
