if (stage === 'document_correction_collection') {
  function getCorrectionReason(doc) {
    return (
      doc?.reason ||
      doc?.correction_reason ||
      doc?.correction_remarks ||
      doc?.remarks ||
      doc?.note ||
      doc?.correction_note ||
      data.current_correction_reason ||
      'Correction required'
    );
  }

  function normalizeCorrectionQueue() {
    let queue = Array.isArray(data.correction_queue)
      ? data.correction_queue
      : [];

    if (!queue.length && Array.isArray(data.required_documents)) {
      queue = data.required_documents.filter((doc) => {
        const status = String(doc?.status || doc?.bot_status || '').toLowerCase();

        return (
          status === 'correction_required' ||
          doc?.correction_required === true ||
          doc?.correction_required === 'true'
        );
      });
    }

    if (!queue.length && data.current_correction_document_code) {
      queue = [{
        description_code: data.current_correction_document_code,
        code: data.current_correction_document_code,
        name: data.current_correction_document_name,
        document_name: data.current_correction_document_name,
        reason: data.current_correction_reason,
        correction_reason: data.current_correction_reason
      }];
    }

    return queue;
  }

  function correctionUploadMessage(doc) {
    const label = getDocLabel(doc);
    const reason = getCorrectionReason(doc);

    if (lang === 'tamil') {
      return [
        'Correction Required',
        '',
        `Document: ${label}`,
        reason ? `Reason: ${reason}` : '',
        '',
        'தயவுசெய்து corrected document-ஐ upload செய்யவும்.',
