      return [
        'Correction Required',
        '',
        `Document: ${label}`,
        reason ? `Reason: ${reason}` : '',
        '',
        'Please corrected document ah upload pannunga.',
        'Indha stage la text reply venam. Corrected document mattum upload pannunga.'
      ].filter(Boolean).join('\n');
    }

    return [
      'Correction Required',
      '',
      `Document: ${label}`,
      reason ? `Reason: ${reason}` : '',
      '',
      'Please upload the corrected document.',
      'At this stage, please upload the corrected document instead of sending a text reply.'
    ].filter(Boolean).join('\n');
