/**
 * SERVICE DATE SELECTION - HARD PRIORITY BLOCK
 *
 * This must run before documents_verified and service_date_fetch.
 * Once available dates are shown, customer reply 1/2 should save the selected date.
 */
if (stage === 'service_date_selection') {
  const availableDates = getAvailableServiceDates(data);
  const selectedOptionNumber = Number(String(msg || '').trim());

  let selected = null;

  // Primary matching: customer replies 1, 2, 3...
  if (
    Number.isInteger(selectedOptionNumber) &&
    selectedOptionNumber >= 1 &&
    selectedOptionNumber <= availableDates.length
  ) {
    selected = availableDates[selectedOptionNumber - 1];
  }

  // Fallback matching: option/number field
  if (!selected) {
    selected = availableDates.find((item, index) => {
      const possibleOptions = [
        item?.option,
        item?.number,
        index + 1,
        String(item?.option || '').replace(/\D/g, ''),
        String(item?.number || '').replace(/\D/g, '')
      ]
        .filter(v => v !== undefined && v !== null && String(v).trim() !== '')
        .map(v => String(v).trim());

      return possibleOptions.includes(String(msg).trim());
    });
  }

  if (!selected) {
    const lines = [
      lang === 'tamil'
        ? 'தயவுசெய்து சரியான தேதி option number-ஐ பதிலளிக்கவும்.'
        : lang === 'tanglish'
          ? 'Correct date option number reply pannunga.'
          : 'Please reply with a valid date option number.',
      ''
    ];

    for (const [index, item] of availableDates.entries()) {
      const option = index + 1;
      const displayDate = getDisplayDate(item);
      const locationText = item.location ? ` - ${item.location}` : '';
      lines.push(`${option}. ${displayDate}${locationText}`);
    }

    const reply = lines.join('\n');

    data.current_stage = 'service_date_selection';
    data.service_date_status = 'waiting_for_customer_selection';
    data.need_service_date_fetch = false;
    data.need_service_date_save = false;
    data.last_reply = reply;

    return [{
      json: {
        ...input,
        output: reply,
        reply,
        last_reply: reply,
        active_service: 'marriage_registration',
        current_stage: 'service_date_selection',
        language,
        session_data: JSON.stringify(data),
        payment_document_handled: true,
