const meta = $('CODE_Prepare_Checklist_Upload_Payload').first().json || {};
const uploadResponse = $json || {};

function parseSession(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;

  try {
    return JSON.parse(raw);
  } catch (e) {
    return {};
  }
}

function isTrue(value) {
  return value === true || value === 'true' || value === 1 || value === '1';
}

function isUploadSuccess(res) {
  return (
    res.success === true ||
    res.ok === true ||
    res.uploaded === true ||
    res.response?.uploaded === true ||
    res.result?.success === true ||
    res.result?.uploaded === true ||
    res.result?.response?.uploaded === true ||
    res.body?.success === true ||
    res.body?.response?.uploaded === true
  );
}

function normalizeLang(lang) {
  const value = String(lang || '').trim().toLowerCase();

  if (value.includes('tamil') || value === 'ta' || value === 'தமிழ்') return 'Tamil';
  if (value.includes('tanglish')) return 'Tanglish';

  return 'English';
}

function getDocCode(item) {
  if (!item || typeof item !== 'object') return '';

  return (
    item.description_code ||
    item.document_code ||
    item.code ||
    item.current_correction_document_code ||
    item.current_document_code ||
    ''
  );
}

function getDocName(item) {
  if (!item || typeof item !== 'object') return '';

  return (
    item.document_name ||
    item.document_label ||
    item.description ||
    item.name ||
    item.current_correction_document_name ||
    item.current_document_name ||
    'Requested Document'
  );
}

function getReason(item) {
  if (!item || typeof item !== 'object') return '';

  return (
    item.reason ||
    item.correction_reason ||
    item.correction_remarks ||
    item.remarks ||
    item.note ||
    item.correction_note ||
    'Correction required'
  );
}

function removeUploadedCorrection(queue, uploadedCode) {
  const codeToRemove = String(uploadedCode || '').trim();

  return (Array.isArray(queue) ? queue : []).filter((item) => {
    const itemCode = String(getDocCode(item) || '').trim();
    return itemCode !== codeToRemove;
  });
}

function buildNextCorrectionReply(language, uploadedLabel, nextCorrection) {
  const nextDocName = getDocName(nextCorrection);
  const reason = getReason(nextCorrection);

  if (language === 'Tamil') {
    return [
      uploadedLabel ? `பெறப்பட்டது: ${uploadedLabel}` : '',
      '',
      'Correction Required',
      '',
      `ஆவணம்: ${nextDocName}`,
      reason ? `காரணம்: ${reason}` : '',
      '',
      'தயவுசெய்து corrected document-ஐ upload செய்யவும்.'
    ].filter(Boolean).join('\n');
  }

  if (language === 'Tanglish') {
    return [
      uploadedLabel ? `Received: ${uploadedLabel}` : '',
      '',
      'Correction Required',
      '',
      `Document: ${nextDocName}`,
      reason ? `Reason: ${reason}` : '',
      '',
      'Please corrected document ah upload pannunga.'
    ].filter(Boolean).join('\n');
  }

  return [
    uploadedLabel ? `Received: ${uploadedLabel}` : '',
    '',
    'Correction Required',
    '',
    `Document: ${nextDocName}`,
    reason ? `Reason: ${reason}` : '',
    '',
    'Please upload the corrected document.'
  ].filter(Boolean).join('\n');
}

function buildAllCorrectionReceivedReply(language, pendingBalance) {
  if (language === 'Tamil') {
    return [
      'நன்றி. தேவையான correction ஆவணங்கள் அனைத்தும் பெறப்பட்டன.',
      '',
      'எங்கள் backend team ஆவணங்களை verify செய்து, correction ஏதேனும் இருந்தால் தெரிவிப்பார்கள்.',
      pendingBalance ? `Balance payment pending: ₹${pendingBalance}` : '',
      pendingBalance ? 'இந்த balance amount final document delivery-க்கு முன் கட்ட வேண்டும்.' : '',
      '',
      'ஆவண verification status அறிய 1 என்று பதிலளிக்கவும்.'
    ].filter(Boolean).join('\n');
  }

  if (language === 'Tanglish') {
    return [
      'Thank you. Required correction documents ellam receive aachu.',
      '',
      'Enga backend team documents verify pannitu, correction irundha update pannuvanga.',
      pendingBalance ? `Balance payment pending: ₹${pendingBalance}` : '',
      pendingBalance ? 'Indha balance amount final document delivery ku munnaadi pay pannanum.' : '',
      '',
      'Document verification status check panna 1 reply pannunga.'
    ].filter(Boolean).join('\n');
  }

  return [
    'Thank you. We have received all required correction documents.',
    '',
    'Our backend team will verify the documents and contact you if any correction is required.',
    pendingBalance ? `Balance payment pending: ₹${pendingBalance}` : '',
    pendingBalance ? 'This balance must be paid before final document delivery.' : '',
    '',
    'Reply 1 to check your document verification status.'
  ].filter(Boolean).join('\n');
}

function buildNormalAllDocumentsReceivedReply(language, pendingBalance) {
  if (language === 'Tamil') {
    return [
      'நன்றி. தேவையான அனைத்து ஆவணங்களையும் பெற்றுள்ளோம்.',
      '',
      'எங்கள் backend team ஆவணங்களை verify செய்து, correction ஏதேனும் இருந்தால் தெரிவிப்பார்கள்.',
      pendingBalance ? `Balance payment pending: ₹${pendingBalance}` : '',
      pendingBalance ? 'இந்த balance amount final document delivery-க்கு முன் கட்ட வேண்டும்.' : '',
      '',
      'ஆவண verification status அறிய 1 என்று பதிலளிக்கவும்.'
    ].filter(Boolean).join('\n');
  }

  if (language === 'Tanglish') {
    return [
      'Thank you. Required documents ellam receive aachu.',
      '',
      'Enga backend team documents verify pannitu, correction irundha update pannuvanga.',
      pendingBalance ? `Balance payment pending: ₹${pendingBalance}` : '',
      pendingBalance ? 'Indha balance amount final document delivery ku munnaadi pay pannanum.' : '',
      '',
      'Document verification status check panna 1 reply pannunga.'
    ].filter(Boolean).join('\n');
  }

  return [
    'Thank you. We have received all required documents.',
    '',
    'Our backend team will verify the documents and contact you if any correction is required.',
    pendingBalance ? `Balance payment pending: ₹${pendingBalance}` : '',
    pendingBalance ? 'This balance must be paid before final document delivery.' : '',
    '',
    'Reply 1 to check your document verification status.'
  ].filter(Boolean).join('\n');
}

function buildUploadFailedReply(language, documentName, reason) {
  if (language === 'Tamil') {
    return [
      'மன்னிக்கவும், file கிடைத்தது ஆனால் backend-ல் save செய்ய முடியவில்லை.',
      '',
      `தயவுசெய்து ${documentName || 'document'} மீண்டும் upload செய்யவும்.`,
      '',
      reason ? `Reason: ${reason}` : ''
    ].filter(Boolean).join('\n');
  }

  if (language === 'Tanglish') {
    return [
      'Sorry, file receive aachu but backend la save panna mudiyala.',
      '',
      `Please ${documentName || 'document'} again upload pannunga.`,
      '',
      reason ? `Reason: ${reason}` : ''
    ].filter(Boolean).join('\n');
  }

  return [
    'Sorry, we received the file but could not save it in the backend.',
    '',
    `Please upload ${documentName || 'the document'} again.`,
    '',
    reason ? `Reason: ${reason}` : ''
  ].filter(Boolean).join('\n');
}

const language = normalizeLang(meta.language || 'English');

const sessionData = parseSession(
  meta.session_data ||
  meta.previous_session_data ||
  '{}'
);

const uploadSuccess = isUploadSuccess(uploadResponse);

const uploadedCode =
  meta.description_code ||
  meta.current_document_code ||
  meta.current_correction_document_code ||
  uploadResponse.response?.description_code ||
  uploadResponse.result?.response?.description_code ||
  uploadResponse.body?.response?.description_code ||
  '';

const uploadedLabel =
  meta.document_name ||
  meta.current_document_name ||
  meta.current_correction_document_name ||
  sessionData.current_document_name ||
  sessionData.current_correction_document_name ||
  uploadedCode ||
  'Document';

const isCorrectionMode =
  isTrue(meta.is_correction_upload) ||
  meta.current_stage === 'document_correction_collection' ||
  meta.current_stage === 'document_correction_pending' ||
  sessionData.current_stage === 'document_correction_collection' ||
  sessionData.current_stage === 'document_correction_pending' ||
  isTrue(sessionData.document_correction_required) ||
  isTrue(sessionData.correction_required) ||
  (Array.isArray(sessionData.correction_queue) && sessionData.correction_queue.length > 0);

if (!uploadSuccess) {
  const reason =
    uploadResponse.message ||
    uploadResponse.result?.message ||
    uploadResponse.body?.message ||
    uploadResponse.error ||
    'Odoo did not confirm upload.';

  const reply = buildUploadFailedReply(language, uploadedLabel, reason);

  sessionData.last_reply = reply;

  return [{
    json: {
      customer_id: meta.customer_id || sessionData.customer_id || '',
      channel: meta.channel || sessionData.channel || 'chat',
      whatsapp_phone: meta.whatsapp_phone || sessionData.whatsapp_phone || '',
      customer_name: meta.customer_name || sessionData.customer_name || '',
      active_service: 'marriage_registration',
      current_stage: isCorrectionMode ? 'document_correction_collection' : 'document_collection',
      language,
      session_data: JSON.stringify(sessionData),
      reply,
      output: reply,
      last_reply: reply,
      updated_at: new Date().toISOString(),

      document_uploaded: false,
      odoo_upload_success: false,
      is_correction_upload: isCorrectionMode,
      uploaded_document_code: uploadedCode,
      uploaded_document_label: uploadedLabel,
      odoo_upload_response: uploadResponse
    }
  }];
}

// --------------------------------------------------
// Correction upload flow
// --------------------------------------------------

if (isCorrectionMode) {
  let correctionQueue = Array.isArray(sessionData.correction_queue)
    ? sessionData.correction_queue
    : [];

  if (!correctionQueue.length && sessionData.current_correction_document_code) {
    correctionQueue = [{
      description_code: sessionData.current_correction_document_code,
      document_name: sessionData.current_correction_document_name,
      reason: sessionData.current_correction_reason
    }];
  }

  const remainingQueue = removeUploadedCorrection(correctionQueue, uploadedCode);
  const nextCorrection = remainingQueue[0] || null;

  sessionData.correction_queue = remainingQueue;
  sessionData.correction_count = remainingQueue.length;

  sessionData.last_uploaded_correction_document_code = uploadedCode;
  sessionData.last_uploaded_correction_document_name = uploadedLabel;
  sessionData.last_uploaded_correction_at = new Date().toISOString();

  sessionData.document_uploaded = true;
  sessionData.odoo_upload_success = true;
  sessionData.documents_status = 'correction_uploaded';

  if (nextCorrection) {
    const nextCode = getDocCode(nextCorrection);
    const nextName = getDocName(nextCorrection);
    const nextReason = getReason(nextCorrection);

    sessionData.current_stage = 'document_correction_collection';
    sessionData.document_correction_required = true;
    sessionData.correction_required = true;

    sessionData.current_correction_document_code = nextCode;
    sessionData.current_correction_document_name = nextName;
    sessionData.current_correction_reason = nextReason;

    sessionData.current_document_code = nextCode;
    sessionData.current_document_name = nextName;
    sessionData.expected_document_code = nextCode;
    sessionData.expected_document_label = nextName;

    const reply = buildNextCorrectionReply(language, uploadedLabel, nextCorrection);
    sessionData.last_reply = reply;

    return [{
      json: {
        customer_id: meta.customer_id || sessionData.customer_id || '',
        channel: meta.channel || sessionData.channel || 'chat',
        whatsapp_phone: meta.whatsapp_phone || sessionData.whatsapp_phone || '',
        customer_name: meta.customer_name || sessionData.customer_name || '',
        active_service: 'marriage_registration',
        current_stage: 'document_correction_collection',
        language,
        session_data: JSON.stringify(sessionData),

        reply,
        output: reply,
        last_reply: reply,
        updated_at: new Date().toISOString(),

        document_uploaded: true,
        odoo_upload_success: true,
        is_correction_upload: true,

        correction_required: true,
        document_correction_required: true,
        correction_count: remainingQueue.length,

        current_correction_document_code: nextCode,
        current_correction_document_name: nextName,
        current_correction_reason: nextReason,

        uploaded_document_code: uploadedCode,
        uploaded_document_label: uploadedLabel,
        odoo_upload_response: uploadResponse
      }
    }];
  }

  sessionData.current_stage = 'documents_pending_verification';
  sessionData.documents_status = 'pending_verification';

  sessionData.document_correction_required = false;
  sessionData.correction_required = false;
  sessionData.correction_queue = [];
  sessionData.correction_count = 0;

  sessionData.current_correction_document_code = '';
  sessionData.current_correction_document_name = '';
  sessionData.current_correction_reason = '';

  sessionData.current_document_code = '';
  sessionData.current_document_name = '';
  sessionData.expected_document_code = '';
  sessionData.expected_document_label = '';

  sessionData.awaiting_document_status_check = true;

  const pendingBalance =
    sessionData.payment_pending_amount ||
    sessionData.pending_balance ||
    sessionData.payment_details?.payment_pending_amount ||
    sessionData.payment_details?.pending_balance ||
    '';

  const reply = buildAllCorrectionReceivedReply(language, pendingBalance);
  sessionData.last_reply = reply;

  return [{
    json: {
      customer_id: meta.customer_id || sessionData.customer_id || '',
      channel: meta.channel || sessionData.channel || 'chat',
      whatsapp_phone: meta.whatsapp_phone || sessionData.whatsapp_phone || '',
      customer_name: meta.customer_name || sessionData.customer_name || '',
      active_service: 'marriage_registration',
      current_stage: 'documents_pending_verification',
      language,
      session_data: JSON.stringify(sessionData),

      reply,
      output: reply,
      last_reply: reply,
      updated_at: new Date().toISOString(),

      document_uploaded: true,
      odoo_upload_success: true,
      is_correction_upload: true,

      correction_required: false,
      document_correction_required: false,
      correction_count: 0,

      uploaded_document_code: uploadedCode,
      uploaded_document_label: uploadedLabel,
      odoo_upload_response: uploadResponse
    }
  }];
}

// --------------------------------------------------
// Normal document collection flow
// --------------------------------------------------

const requiredDocuments = Array.isArray(sessionData.required_documents)
  ? sessionData.required_documents
  : [];

let currentIndex = Number(
  meta.current_document_index !== undefined
    ? meta.current_document_index
    : sessionData.current_document_index || 0
);

if (Number.isNaN(currentIndex)) currentIndex = 0;

const nextIndex = currentIndex + 1;
const nextDocument = requiredDocuments[nextIndex] || null;

sessionData.document_uploaded = true;
sessionData.odoo_upload_success = true;
sessionData.last_uploaded_document_code = uploadedCode;
sessionData.last_uploaded_document_name = uploadedLabel;
sessionData.last_uploaded_at = new Date().toISOString();

sessionData.current_document_index = nextIndex;

if (nextDocument) {
  const nextCode = getDocCode(nextDocument);
  const nextName = getDocName(nextDocument);

  sessionData.current_stage = 'document_collection';
  sessionData.current_document_code = nextCode;
  sessionData.current_document_name = nextName;
  sessionData.expected_document_code = nextCode;
  sessionData.expected_document_label = nextName;

  const reply = [
    `Received: ${uploadedLabel}`,
    '',
    `Please upload: ${nextName}`
  ].join('\n');

  sessionData.last_reply = reply;

  return [{
    json: {
      customer_id: meta.customer_id || sessionData.customer_id || '',
      channel: meta.channel || sessionData.channel || 'chat',
      whatsapp_phone: meta.whatsapp_phone || sessionData.whatsapp_phone || '',
      customer_name: meta.customer_name || sessionData.customer_name || '',
      active_service: 'marriage_registration',
      current_stage: 'document_collection',
      language,
      session_data: JSON.stringify(sessionData),

      reply,
      output: reply,
      last_reply: reply,
      updated_at: new Date().toISOString(),

      document_uploaded: true,
      odoo_upload_success: true,
      is_correction_upload: false,

      current_document_index: nextIndex,
      current_document_code: nextCode,
      current_document_name: nextName,

      uploaded_document_code: uploadedCode,
      uploaded_document_label: uploadedLabel,
      odoo_upload_response: uploadResponse
    }
  }];
}

sessionData.current_stage = 'documents_pending_verification';
sessionData.documents_status = 'pending_verification';
sessionData.current_document_code = '';
sessionData.current_document_name = '';
sessionData.expected_document_code = '';
sessionData.expected_document_label = '';
sessionData.awaiting_document_status_check = true;

const pendingBalance =
  sessionData.payment_pending_amount ||
  sessionData.pending_balance ||
  sessionData.payment_details?.payment_pending_amount ||
  sessionData.payment_details?.pending_balance ||
  '';

const reply = buildNormalAllDocumentsReceivedReply(language, pendingBalance);
sessionData.last_reply = reply;

return [{
  json: {
    customer_id: meta.customer_id || sessionData.customer_id || '',
    channel: meta.channel || sessionData.channel || 'chat',
    whatsapp_phone: meta.whatsapp_phone || sessionData.whatsapp_phone || '',
    customer_name: meta.customer_name || sessionData.customer_name || '',
    active_service: 'marriage_registration',
    current_stage: 'documents_pending_verification',
    language,
    session_data: JSON.stringify(sessionData),

    reply,
    output: reply,
    last_reply: reply,
    updated_at: new Date().toISOString(),

    document_uploaded: true,
    odoo_upload_success: true,
    is_correction_upload: false,

    uploaded_document_code: uploadedCode,
    uploaded_document_label: uploadedLabel,
    odoo_upload_response: uploadResponse
  }
}];

const input = $input.first().json || {};

function parseSession(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;

  try {
    return JSON.parse(raw);
  } catch (e) {
    return {};
  }
}

function isTrue(value) {
  return value === true || value === 'true' || value === 1 || value === '1';
}

function getDocCode(item) {
  if (!item || typeof item !== 'object') return '';

  return (
    item.description_code ||
    item.document_code ||
    item.code ||
    item.current_correction_document_code ||
    item.current_document_code ||
    ''
  );
}

function getDocName(item) {
  if (!item || typeof item !== 'object') return '';

  return (
    item.document_name ||
    item.document_label ||
    item.description ||
    item.name ||
    item.current_correction_document_name ||
    item.current_document_name ||
    'Requested Document'
  );
}

function getReason(item) {
  if (!item || typeof item !== 'object') return '';

  return (
    item.reason ||
    item.correction_reason ||
    item.correction_remarks ||
    item.remarks ||
    item.note ||
    item.correction_note ||
    ''
  );
}

const data = parseSession(input.session_data);

const correctionQueue = Array.isArray(data.correction_queue)
  ? data.correction_queue
  : [];

const firstCorrectionItem = correctionQueue[0] || {};

const isCorrectionUpload =
  isTrue(input.is_correction_upload) ||
  input.current_stage === 'document_correction_collection' ||
  input.current_stage === 'document_correction_pending' ||
  data.current_stage === 'document_correction_collection' ||
  data.current_stage === 'document_correction_pending' ||
  data.current_stage === 'correction_collection' ||
  data.current_stage === 'correction_pending' ||
  data.documents_status === 'uploading_correction_document' ||
  isTrue(data.document_correction_required) ||
  isTrue(data.correction_required) ||
  correctionQueue.length > 0;

if (input.need_document_upload_to_odoo !== true) {
  return [
    {
      json: {
        ...input,
        output: input.output || input.reply || 'Please continue.',
        reply: input.reply || input.output || 'Please continue.',
        need_document_upload_to_odoo: false,
        skipped_upload_prepare: true,
        is_correction_upload: isCorrectionUpload
      }
    }
  ];
}

let base64Data = input.attachment_base64 || '';
let filename = input.attachment_file_name || 'uploaded_document';
let mimetype = input.attachment_mime_type || 'application/octet-stream';

const binaryKey = input.attachment_binary_key || 'data0';

if (!base64Data) {
  if ($binary && $binary[binaryKey]) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
    base64Data = buffer.toString('base64');

    filename = $binary[binaryKey].fileName || filename;
    mimetype = $binary[binaryKey].mimeType || mimetype;
  }
}

if (!base64Data) {
  throw new Error(
    `No attachment base64 or binary file found. binaryKey=${binaryKey}, file=${filename}`
  );
}

const serviceCategory = String(
  data.service_details?.service_category ||
  data.service_category ||
  ''
).toLowerCase();

let serviceCode =
  data.service_details?.service_code ||
  data.service_details?.service_code_for_fee ||
  data.service_details?.selected_service_option_backend ||
  data.selected_service_option_backend ||
  data.service_code ||
  data.service_code_for_fee ||
  data.selected_service_option ||
  '';

if (!serviceCode) {
  if (serviceCategory.includes('muslim')) serviceCode = 'muslim_marriage';
  else if (serviceCategory.includes('christian')) serviceCode = 'christian_marriage';
  else if (serviceCategory.includes('special')) serviceCode = 'special_marriage';
  else if (serviceCategory.includes('hindu')) serviceCode = 'hindu_marriage';
  else serviceCode = 'muslim_marriage';
}

const leadId =
  data.odoo_lead_id ||
  data.lead_id ||
  data.lead_details?.odoo_lead_id ||
  data.lead_details?.lead_id ||
  input.odoo_lead_id ||
  input.lead_id ||
  '';

const requestNumber =
  data.odoo_request_number ||
  data.request_number ||
  data.lead_details?.odoo_request_number ||
  data.lead_details?.request_number ||
  input.odoo_request_number ||
  input.request_number ||
  '';

const descriptionCode = isCorrectionUpload
  ? (
      input.current_correction_document_code ||
      data.current_correction_document_code ||
      getDocCode(firstCorrectionItem) ||
      input.current_document_code ||
      data.current_document_code ||
      data.expected_document_code ||
      ''
    )
  : (
      input.current_document_code ||
      data.current_document_code ||
      data.expected_document_code ||
      ''
    );

const documentName = isCorrectionUpload
  ? (
      input.current_correction_document_name ||
      data.current_correction_document_name ||
      getDocName(firstCorrectionItem) ||
      input.current_document_name ||
      data.current_document_name ||
      data.expected_document_label ||
      ''
    )
  : (
      input.current_document_name ||
      data.current_document_name ||
      data.expected_document_label ||
      ''
    );

const correctionReason = isCorrectionUpload
  ? (
      input.current_correction_reason ||
      data.current_correction_reason ||
      getReason(firstCorrectionItem) ||
      data.correction_reason ||
      data.correction_note ||
      data.correction_remarks ||
      ''
    )
  : '';

if (!leadId) {
  throw new Error('Missing lead_id / odoo_lead_id. Cannot upload checklist document.');
}

if (!requestNumber) {
  throw new Error('Missing request_number / odoo_request_number. Cannot upload checklist document.');
}

if (!descriptionCode) {
  throw new Error('Missing description_code/current_document_code. Cannot identify checklist item.');
}

const odooPayload = {
  lead_id: leadId,
  request_number: requestNumber,
  service_code: serviceCode,
  description_code: descriptionCode,
  bot_customer_id: input.customer_id || data.bot_customer_id || data.customer_id || '',
  attachment: {
    data: base64Data,
    filename,
    mimetype
  }
};

return [
  {
    json: {
      lead_id: leadId,
      request_number: requestNumber,
      service_code: serviceCode,
      description_code: descriptionCode,
      document_name: documentName,
      bot_customer_id: input.customer_id || data.bot_customer_id || data.customer_id || '',

      is_correction_upload: isCorrectionUpload,
      correction_reason: correctionReason,
      correction_queue: correctionQueue,
      correction_count: correctionQueue.length,

      attachment: {
        filename,
        mimetype,
        data: base64Data
      },

      odoo_payload: odooPayload,

      session_data: input.session_data,

      current_document_index: Number(
        input.current_document_index !== undefined
          ? input.current_document_index
          : data.current_document_index || 0
      ),

      current_document_code: descriptionCode,
      current_document_name: documentName,

      current_correction_document_code: isCorrectionUpload ? descriptionCode : '',
      current_correction_document_name: isCorrectionUpload ? documentName : '',
      current_correction_reason: correctionReason,

      attachment_info: input.attachment_info || `${filename} | ${mimetype}`,
      attachment_file_name: filename,
      attachment_mime_type: mimetype,

      customer_id: input.customer_id || data.customer_id || '',
      channel: input.channel || data.channel || 'chat',
      language: input.language || data.language || 'English',
      active_service: input.active_service || data.active_service || 'marriage_registration',
      current_stage: input.current_stage || data.current_stage || ''
    }
  }
];

const input = $input.first().json || {};
const body = input.body || input || {};

const correctionItems = Array.isArray(body.correction_items)
  ? body.correction_items
  : [];

const customerId =
  body.bot_customer_id ||
  body.bot_session_id ||
  '';

return [
