        status: 'correction_required',
        index
      })),

      received_at: new Date().toISOString()
    }
  }
];

const correction = $('CODE_Normalize_Document_Correction').item.json;
const row = $input.first().json || {};

function parseSession(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;

  try {
    return JSON.parse(raw);
  } catch (e) {
    return {};
  }
}

const data = parseSession(row.session_data);

const correctionItems = Array.isArray(correction.correction_items)
  ? correction.correction_items
  : [];

const docs = Array.isArray(data.required_documents)
  ? data.required_documents
  : [];

/**
 * Merge correction items into required_documents.
 */
for (const correctionItem of correctionItems) {
  const code = correctionItem.description_code || correctionItem.code || '';

  if (!code) continue;

  const existingIndex = docs.findIndex((doc) => {
    const docCode = doc.code || doc.description_code || '';
    return docCode === code;
  });

  if (existingIndex >= 0) {
    docs[existingIndex] = {
      ...docs[existingIndex],
      name: docs[existingIndex].name || correctionItem.name || code,
      code,
      description_code: code,

      status: 'correction_required',
      correction_required: true,
      correction_reason: correctionItem.reason || 'Please upload the correct document.',
      correction_requested_at: correction.received_at,

      is_data_required: correctionItem.is_data_required === true,
      is_attachment_required: correctionItem.is_attachment_required !== false
    };
  } else {
    docs.push({
      name: correctionItem.name || code,
      code,
      description_code: code,

      is_data_required: correctionItem.is_data_required === true,
      is_attachment_required: correctionItem.is_attachment_required !== false,

      status: 'correction_required',
      correction_required: true,
      correction_reason: correctionItem.reason || 'Please upload the correct document.',
      correction_requested_at: correction.received_at,

      attachment_info: '',
      uploaded_at: '',
      index: docs.length
    });
  }
}

/**
 * Rebuild correction queue from required documents.
 */
const correctionQueue = docs
  .map((doc, index) => ({
    ...doc,
    index
  }))
  .filter((doc) =>
    doc.status === 'correction_required' ||
    doc.correction_required === true ||
    doc.correction_required === 'true'
  );

const firstCorrection = correctionQueue[0];

data.required_documents = docs;
data.correction_queue = correctionQueue;

data.documents_status = firstCorrection ? 'correction_required' : 'pending_verification';
data.documents_collected = false;
data.document_correction_required = !!firstCorrection;

data.current_document_index = firstCorrection
  ? firstCorrection.index
  : data.current_document_index || 0;

data.current_document_code = firstCorrection
  ? firstCorrection.code || firstCorrection.description_code || ''
  : data.current_document_code || '';

data.current_document_name = firstCorrection
  ? firstCorrection.name || ''
  : data.current_document_name || '';

data.correction_event = correction.event || 'document_correction_required';
data.correction_received_at = correction.received_at || new Date().toISOString();

data.odoo_lead_id = correction.lead_id || data.odoo_lead_id || '';
data.odoo_request_number = correction.request_number || data.odoo_request_number || '';
data.service_code = correction.service_code || data.service_code || '';

/**
 * Controlled customer flow:
 * Do not directly ask for upload in webhook reply.
 * Store summary. Customer should reply 1 to view correction document.
 */
let reply = '';

if (firstCorrection) {
  reply = [
    'Document correction is required.',
    '',
    `Correction documents pending: ${correctionQueue.length}`,
    '',
    'Reply 1 to view the required correction document.'
  ].join('\n');
} else {
  reply = 'Document correction request received, but no correction item was found.';
}

data.correction_summary_message = reply;

return [
  {
    json: {
      id: row.id || '',
      customer_id: row.customer_id || correction.customer_id,
      channel: row.channel || correction.channel || 'chat',
      active_service: row.active_service || 'marriage_registration',

      current_stage: firstCorrection
        ? 'document_correction_collection'
        : row.current_stage || 'documents_pending_verification',

      language: row.language || 'English',
      session_data: JSON.stringify(data),
      updated_at: new Date().toISOString(),
      last_reply: reply,

      webhook_success: true,
      correction_count: correctionQueue.length,

      output: reply,
      reply
    }
  }
];

