const httpResponse = $input.first().json || {};
const previous = $('CODE_Payment_Document_Handler').item.json || {};

function parseSession(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;
  try {
    return JSON.parse(raw);
  } catch (e) {
    return {};
  }
}

function formatDate(dateValue) {
  if (!dateValue) return '';

  const text = String(dateValue).trim();

  // YYYY-MM-DD -> DD/MM/YYYY
  const parts = text.split('-');
  if (parts.length === 3 && parts[0].length === 4) {
    return `${parts[2]}/${parts[1]}/${parts[0]}`;
  }

  return text;
}

function normalizeLang(lang) {
  const value = String(lang || '').trim().toLowerCase();
  if (value.includes('tamil') || value === 'ta' || value === 'தமிழ்') return 'Tamil';
  if (value.includes('tanglish')) return 'Tanglish';
  return 'English';
}

function replyByLanguage(language, english, tamil, tanglish) {
  const lang = normalizeLang(language);
  if (lang === 'Tamil') return tamil;
  if (lang === 'Tanglish') return tanglish;
  return english;
}

const data = parseSession(previous.session_data);
const language = normalizeLang(previous.language || data.language || 'English');

const availableDates =
  httpResponse.available_dates ||
  httpResponse.data?.available_dates ||
  httpResponse.result?.available_dates ||
  httpResponse.response?.available_dates ||
  [];

if (!Array.isArray(availableDates) || availableDates.length === 0) {
  data.service_date_status = 'no_dates_available';
  data.available_service_dates = [];
  data.current_stage = 'documents_verified';
  data.awaiting_registration_date_selection = true;

  const reply = replyByLanguage(
    language,
    [
      'Currently, no registration dates are available.',
      '',
      'Our backend team will contact you once dates are available.'
    ].join('\n'),
    [
      'தற்போது பதிவு தேதிகள் கிடைக்கவில்லை.',
      '',
      'தேதிகள் கிடைத்தவுடன் எங்கள் backend குழு உங்களை தொடர்பு கொள்வார்கள்.'
    ].join('\n'),
    [
      'Ippo registration dates available illa.',
      '',
      'Dates available aanadhum backend team unga contact pannuvanga.'
    ].join('\n')
  );

  data.last_reply = reply;

  return [
    {
      json: {
        ...previous,
        output: reply,
        reply,
        last_reply: reply,

        active_service: 'marriage_registration',
        current_stage: 'documents_verified',
        language,

        session_data: JSON.stringify(data),

        payment_document_handled: true,
        need_document_checklist: false,
        need_document_upload_to_odoo: false,
        is_correction_upload: false,
        need_service_date_fetch: false,
        need_service_date_save: false,
        close_session: false
      }
    }
  ];
}

const normalizedDates = availableDates.map((item, index) => {
  const rawDate =
    item.date ||
    item.available_date ||
    item.selected_date ||
    item.service_date ||
    '';

  return {
    option: index + 1,
    number: index + 1,
    date: rawDate,
    available_date: rawDate,
    display_date: item.display_date || formatDate(rawDate),
    location: item.location || item.venue || ''
  };
});

data.available_service_dates = normalizedDates;
data.service_date_status = 'waiting_for_customer_selection';

/**
 * CRITICAL FIX:
 * This must be saved inside session_data also.
 * Otherwise next customer reply again reads service_date_fetch and fetches dates repeatedly.
 */
data.current_stage = 'service_date_selection';
data.need_service_date_fetch = false;
data.need_service_date_save = false;
data.awaiting_registration_date_selection = false;

const groupedByMonth = {};

for (const item of normalizedDates) {
  const display = item.display_date || formatDate(item.date);
  const parts = display.split('/');
  const monthYear = parts.length === 3 ? `${parts[1]}/${parts[2]}` : 'Available Dates';

  if (!groupedByMonth[monthYear]) {
    groupedByMonth[monthYear] = [];
  }

  groupedByMonth[monthYear].push(item);
}

let lines = [];

if (language === 'Tamil') {
  lines = [
    'கிடைக்கும் பதிவு தேதிகள்:',
    ''
  ];

  for (const [monthYear, items] of Object.entries(groupedByMonth)) {
    lines.push(`மாதம்: ${monthYear}`);
    for (const item of items) {
      const locationText = item.location ? ` - ${item.location}` : '';
      lines.push(`${item.option}. ${item.display_date}${locationText}`);
    }
    lines.push('');
  }

  lines.push('பதிவு தேதியை தேர்வு செய்ய option number-ஐ பதிலளிக்கவும்.');
} else if (language === 'Tanglish') {
  lines = [
    'Available registration dates:',
    ''
  ];

  for (const [monthYear, items] of Object.entries(groupedByMonth)) {
    lines.push(`Month: ${monthYear}`);
    for (const item of items) {
      const locationText = item.location ? ` - ${item.location}` : '';
      lines.push(`${item.option}. ${item.display_date}${locationText}`);
    }
    lines.push('');
  }

  lines.push('Registration date select panna option number reply pannunga.');
} else {
  lines = [
    'Available registration dates:',
    ''
  ];

  for (const [monthYear, items] of Object.entries(groupedByMonth)) {
    lines.push(`Month: ${monthYear}`);
    for (const item of items) {
      const locationText = item.location ? ` - ${item.location}` : '';
      lines.push(`${item.option}. ${item.display_date}${locationText}`);
    }
    lines.push('');
  }

  lines.push('Please reply with the option number to select your registration date.');
