function normalizeLang(lang) {
  const value = String(lang || '').trim().toLowerCase();

  if (value.includes('tamil') || value === 'ta' || value === 'தமிழ்') return 'Tamil';
  if (value.includes('tanglish')) return 'Tanglish';

  return 'English';
}

function replyByLanguage(language, english, tamil, tanglish) {
  const lang = normalizeLang(language);

  if (lang === 'Tamil') return tamil;
  if (lang === 'Tanglish') return tanglish;

  return english;
}

function toServiceCode(serviceName) {
  const value = String(serviceName || '').trim().toLowerCase();

  if (value.includes('both')) return 'hindu_and_tamilnadu_marriage';
  if (value.includes('tamilnadu')) return 'tamilnadu_marriage';
  if (value.includes('hindu')) return 'hindu_marriage';
  if (value.includes('muslim')) return 'muslim_marriage';
  if (value.includes('christian')) return 'christian_marriage';
  if (value.includes('special')) return 'special_marriage';

  return 'marriage_registration';
}

// IMPORTANT FIX:
// Do NOT return input.data here.
// If we return input.data, we lose input.success.
// Your HTTP node response is:
// { success: true, message: "...", data: { services: [], options: {} } }
function getResponseObject(input) {
  return (
    input.result ||
    input.body ||
    input
  );
}

function getPayload(response) {
  return (
    response.data ||
    response.response ||
    response.result?.data ||
    response.result?.response ||
    response.body?.data ||
    response.body?.response ||
    response
  );
}

function isSuccess(response) {
  return (
    response.success === true ||
    response.result?.success === true ||
    response.body?.success === true ||
    response.data?.success === true
  );
}

function normalizeServices(services) {
  if (!Array.isArray(services)) return [];

  return services
    .filter((service) => service)
    .map((service, index) => {
      const serviceName =
        service.service_name ||
        service.name ||
        service.display_name ||
        '';

      return {
        number: String(index + 1),
        service_id: service.service_id || service.id || '',
        service_name: serviceName,
        service_code: service.service_code || service.code || toServiceCode(serviceName)
      };
    })
    .filter((service) => service.service_name);
}

function normalizeOptions(options) {
  if (!options || typeof options !== 'object' || Array.isArray(options)) {
    return {};
  }

  return options;
}

function serviceLines(services) {
  return services
    .map((service) => `${service.number}. ${service.service_name}`)
    .join('\n');
}

function placeLines(options) {
  return Object.entries(options || {})
    .map(([key, label], index) => `${index + 1}. ${label}`)
    .join('\n');
}

function optionCount(options) {
  return Object.keys(options || {}).length;
}

function buildServiceSelectionReply(language, services) {
  const count = services.length;

  return replyByLanguage(
    language,
    [
      'Please choose the marriage registration service:',
      '',
      serviceLines(services),
      '',
      `Please reply with 1 to ${count}.`
    ].join('\n'),

    [
      'தயவுசெய்து திருமண பதிவு சேவையை தேர்வு செய்யவும்:',
      '',
      serviceLines(services),
      '',
      `தயவுசெய்து 1 முதல் ${count} வரை பதிலளிக்கவும்.`
    ].join('\n'),

    [
      'Marriage registration service select pannunga:',
      '',
      serviceLines(services),
      '',
      `1 to ${count} la one option reply pannunga.`
    ].join('\n')
  );
}

