  data.marriage_date_for_options =
    previous.marriage_date_for_options ||
    data.marriage_date_for_options ||
    payload.marriage_date ||
    marriageDate ||
    '';

  data.marriage = {
    ...(data.marriage || {}),
    marriage_date: marriageDate,
    marriage_place: marriagePlace,
    registration_place_option: registrationPlaceOption,
    registration_place_label: registrationPlaceLabel
