function parseSession(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;

  try {
    return JSON.parse(raw);
  } catch (e) {
    return {};
  }
}

function normalizeLang(lang) {
  const value = String(lang || '').trim().toLowerCase();
  if (value.includes('tamil') || value === 'ta') return 'tamil';
  if (value.includes('tanglish')) return 'tanglish';
  return 'english';
}

function getPayload(input) {
  return (
    input.result?.response ||
    input.result?.data ||
    input.result ||
    input.body?.response ||
    input.body?.data ||
    input.body ||
    input.response ||
    input.data ||
    input
  );
}

function findChecklistLines(obj) {
  if (!obj || typeof obj !== 'object') return [];

  if (Array.isArray(obj)) return obj;

  const direct =
    obj.response ||
    obj.checklist ||
    obj.checklist_lines ||
    obj.documents ||
    obj.required_documents ||
    obj.service_checklist_line ||
    obj.service_checklist_lines ||
    obj.checklist_items ||
    obj.lines;

  if (Array.isArray(direct)) return direct;

  const nested =
    obj.response?.checklist ||
    obj.response?.checklist_lines ||
    obj.response?.documents ||
    obj.response?.service_checklist_line ||
    obj.response?.service_checklist_lines ||
    obj.response?.lines ||
    obj.checklist?.service_checklist_line ||
    obj.checklist?.service_checklist_lines ||
    obj.checklist?.lines ||
    obj.service_checklist?.service_checklist_line ||
    obj.service_checklist?.service_checklist_lines ||
    obj.service_checklist?.lines;

  if (Array.isArray(nested)) return nested;

  for (const value of Object.values(obj)) {
    if (Array.isArray(value)) {
      if (
        value.some(line =>
          line &&
          typeof line === 'object' &&
          (
            line.code ||
            line.description_code ||
            line.document_code ||
            line.name ||
            line.description ||
            line.document_name
          )
        )
      ) {
        return value;
      }
    }

    if (value && typeof value === 'object') {
      const found = findChecklistLines(value);
      if (found.length) return found;
    }
  }

  return [];
}

function boolValue(value) {
  return (
    value === true ||
    value === 'true' ||
    value === 1 ||
    value === '1' ||
    value === 'yes' ||
    value === 'Yes'
  );
}

/**
 * IMPORTANT:
 * Only attachment-required documents should be asked from customer.
 */
function isAttachmentRequired(line) {
  if (!line || typeof line !== 'object') return false;

  if (line.is_attachment_required !== undefined) {
    return boolValue(line.is_attachment_required);
  }

  if (line.attachment_required !== undefined) {
    return boolValue(line.attachment_required);
  }

  if (line.required !== undefined) {
    return boolValue(line.required);
  }

  /**
   * If backend does not send requirement field, safer fallback is true.
   * But your backend now sends is_attachment_required, so this should rarely happen.
   */
  return true;
}

function isDataRequired(line) {
  if (!line || typeof line !== 'object') return false;

  if (line.is_data_required !== undefined) {
    return boolValue(line.is_data_required);
  }

  if (line.data_required !== undefined) {
    return boolValue(line.data_required);
  }

  return false;
}

function getDocCode(doc) {
  return doc?.description_code || doc?.code || doc?.document_code || '';
}

function getDocLabel(doc) {
  return (
    doc?.label ||
    doc?.name ||
    doc?.description ||
    doc?.document_name ||
    getDocCode(doc) ||
    'the document'
  );
}

function getDocumentGroup(doc) {
  const code = String(doc.description_code || doc.code || '').toLowerCase();
  const label = String(doc.label || doc.name || '').toLowerCase();

  const backendGroup = String(
    doc.document_group ||
    doc.group ||
    doc.category ||
    ''
  ).toLowerCase();

  if (backendGroup.includes('bride')) return 'bride';
  if (backendGroup.includes('groom')) return 'groom';
  if (backendGroup.includes('marriage')) return 'marriage';
  if (backendGroup.includes('common')) return 'marriage';

  if (code.startsWith('bride_') || code.includes('_bride_') || label.includes('bride')) {
    return 'bride';
  }

  if (code.startsWith('groom_') || code.includes('_groom_') || label.includes('groom')) {
    return 'groom';
  }

  return 'marriage';
}

function isUploadedOrBackendDone(doc) {
  const status = String(doc.bot_status || doc.status || '').toLowerCase();

  return (
    doc.uploaded === true ||
    doc.uploaded === 'true' ||
    status === 'uploaded' ||
    status === 'approved' ||
    status === 'correction_uploaded'
  );
}

function isRejected(doc) {
  const status = String(doc.bot_status || doc.status || '').toLowerCase();
  return status === 'rejected';
}

function groupRequiredDocuments(requiredDocs) {
  const groups = {
    bride: [],
    groom: [],
    marriage: [],
    other: []
  };

  for (const doc of requiredDocs) {
    const group = getDocumentGroup(doc);

    if (groups[group]) {
      groups[group].push(doc);
    } else {
      groups.other.push(doc);
    }
  }

  return groups;
}

function buildGroupedDocumentLines(requiredDocs, lang) {
  const groups = groupRequiredDocuments(requiredDocs);
  const sections = [];

  function buildSection(title, docs) {
    if (!docs.length) return '';

    const lines = docs
      .map((doc, index) => `${index + 1}. ${getDocLabel(doc)}`)
      .join('\n');

    return `${title}\n${lines}`;
  }

  if (lang === 'tamil') {
    sections.push(buildSection('👰 மணமகள் ஆவணங்கள்', groups.bride));
    sections.push(buildSection('🤵 மணமகன் ஆவணங்கள்', groups.groom));
    sections.push(buildSection('💍 திருமண ஆவணங்கள்', groups.marriage));
    sections.push(buildSection('📌 மற்ற ஆவணங்கள்', groups.other));
  } else {
    sections.push(buildSection('👰 Bride Documents', groups.bride));
    sections.push(buildSection('🤵 Groom Documents', groups.groom));
    sections.push(buildSection('💍 Marriage Documents', groups.marriage));
    sections.push(buildSection('📌 Other Documents', groups.other));
  }

  return sections.filter(Boolean).join('\n\n');
}

