      current_stage: 'document_checklist_fetch_failed',
      language: lang,
      need_document_checklist: true,
      document_collection_completed: false,
      awaiting_document_upload_start: false,
      awaiting_document_status_check: false,
      checklist_debug_payload_keys: Object.keys(payload || {}),
      reply,
      output: reply,
      last_reply: reply,
      session_data: JSON.stringify(data)
    }
  }];
}

/**
 * Normalize all checklist lines.
 * Do NOT create custom Odoo bot_status.
 * Keep backend bot_status as received.
 */
const normalizedChecklist = checklist.map((line, index) => {
  const descriptionCode =
    line.description_code ||
    line.code ||
    line.document_code ||
    line.name_code ||
    '';

  const label =
    line.description ||
    line.label ||
    line.name ||
    line.document_name ||
    line.checklist_name ||
    descriptionCode;

  const attachmentRequired = isAttachmentRequired(line);
  const dataRequired = isDataRequired(line);
  const backendStatus = String(line.bot_status || line.status || 'pending').toLowerCase();

  const doc = {
    index,
    description_code: descriptionCode,
    code: descriptionCode,
    label,
    name: label,

    /**
     * These are n8n session flags.
     * required means customer must upload attachment.
     */
    required: attachmentRequired,
    is_attachment_required: attachmentRequired,
    is_data_required: dataRequired,

    /**
     * Keep Odoo status only.
     */
    bot_status: backendStatus,
    status: backendStatus,

    uploaded:
      line.uploaded === true ||
      line.uploaded === 'true' ||
      backendStatus === 'uploaded' ||
      backendStatus === 'approved' ||
      backendStatus === 'correction_uploaded',

    upload_later: false,

    /**
     * Session-only helper.
     * Not sent to Odoo.
     */
    skipped: attachmentRequired === false,
    skip_reason: attachmentRequired === false ? 'attachment_not_required' : ''
  };

  doc.document_group = getDocumentGroup(doc);

  return doc;
});

/**
 * IMPORTANT:
 * requiredDocuments must include only is_attachment_required = true.
 * Non-mandatory documents remain in optionalDocuments only.
 */
const requiredDocuments = normalizedChecklist.filter(doc =>
  doc.is_attachment_required === true
);

const optionalDocuments = normalizedChecklist.filter(doc =>
  doc.is_attachment_required !== true
);

const pendingRequiredDocs = requiredDocuments.filter(doc =>
  !isUploadedOrBackendDone(doc) &&
  !isRejected(doc)
);

let reply = '';
let currentStage = '';

if (pendingRequiredDocs.length > 0) {
  currentStage = 'document_checklist_ready';

  const checklistReply = buildChecklistReadyMessage(pendingRequiredDocs, lang);
  const paymentStatusReply = getPaymentStatusReply(previous, data);

  reply = paymentStatusReply
    ? `${paymentStatusReply}\n\n${checklistReply}`
    : checklistReply;

  data.current_stage = currentStage;
  data.document_checklist = normalizedChecklist;
  data.required_documents = requiredDocuments;
  data.optional_documents = optionalDocuments;
  data.pending_required_documents = pendingRequiredDocs;

  data.awaiting_document_upload_start = true;
  data.document_collection_started = false;
  data.document_collection_completed = false;
  data.has_pending_later_documents = false;
  data.awaiting_document_status_check = false;

  data.expected_document_code = '';
  data.expected_document_label = '';
  data.current_document_code = '';
  data.current_document_label = '';
  data.current_document_name = '';

  data.last_reply = reply;
} else {
  currentStage = 'document_verification_pending';

  const checklistReply = noRequiredDocumentsMessage(lang);
  const paymentStatusReply = getPaymentStatusReply(previous, data);

  reply = paymentStatusReply
    ? `${paymentStatusReply}\n\n${checklistReply}`
    : checklistReply;

  data.current_stage = currentStage;
  data.document_checklist = normalizedChecklist;
  data.required_documents = requiredDocuments;
  data.optional_documents = optionalDocuments;
  data.pending_required_documents = [];

  data.awaiting_document_upload_start = false;
  data.document_collection_started = false;
  data.document_collection_completed = true;
  data.has_pending_later_documents = false;
  data.awaiting_document_status_check = true;

  data.expected_document_code = '';
  data.expected_document_label = '';
  data.current_document_code = '';
  data.current_document_label = '';
  data.current_document_name = '';

  data.last_reply = reply;
}

return [{
  json: {
    ...previous,
    current_stage: currentStage,
    language: lang,

    document_checklist: normalizedChecklist,
    required_documents: requiredDocuments,
    optional_documents: optionalDocuments,
    pending_required_documents: pendingRequiredDocs,

    awaiting_document_upload_start: data.awaiting_document_upload_start,
    document_collection_started: data.document_collection_started,
    document_collection_completed: data.document_collection_completed,
    has_pending_later_documents: data.has_pending_later_documents,
    awaiting_document_status_check: data.awaiting_document_status_check,

    expected_document_code: data.expected_document_code,
    expected_document_label: data.expected_document_label,
    current_document_code: data.current_document_code,
    current_document_label: data.current_document_label,
    current_document_name: data.current_document_name,

    payment_status_reply: data.payment_status_reply || previous.payment_status_reply || '',
    payment_summary_message: data.payment_summary_message || previous.payment_summary_message || '',

    reply,
    output: reply,
    last_reply: reply,
    session_data: JSON.stringify(data)
  }
}];

const httpInput = $input.first().json || {};

// This node is after HTTP_Get_Checklist_From_Odoo.
// So $json is the HTTP response. We read previous session from IF_Need_Document_Checklist.
let previous = {};
try {
  previous = $('IF_Need_Document_Checklist').first().json || {};
} catch (e) {
  previous = {};
}

function parseSession(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;
  try {
    return JSON.parse(raw);
  } catch (e) {
    return {};
  }
}

function getPayload(input) {
  return (
    input.result?.response ||
    input.result?.data ||
    input.result ||
    input.body?.response ||
    input.body?.data ||
    input.body ||
    input.response ||
    input.data ||
    input
  );
}

function findChecklistLines(obj) {
  if (!obj || typeof obj !== 'object') return [];

  // Your backend response is expected as:
  // { success: true, response: [ { name, code, is_data_required, is_attachment_required } ] }
  if (Array.isArray(obj)) return obj;

  const direct =
    obj.response ||
    obj.checklist ||
    obj.checklist_lines ||
    obj.documents ||
    obj.required_documents ||
    obj.service_checklist_line ||
    obj.service_checklist_lines ||
    obj.checklist_items ||
    obj.lines;

  if (Array.isArray(direct)) return direct;

  const nested =
    obj.response?.checklist ||
    obj.response?.checklist_lines ||
    obj.response?.documents ||
    obj.response?.service_checklist_line ||
    obj.response?.service_checklist_lines ||
    obj.response?.lines ||
    obj.checklist?.service_checklist_line ||
    obj.checklist?.service_checklist_lines ||
    obj.checklist?.lines ||
    obj.service_checklist?.service_checklist_line ||
    obj.service_checklist?.service_checklist_lines ||
    obj.service_checklist?.lines;

  if (Array.isArray(nested)) return nested;

  // Last fallback: deep search for first array containing document code/name.
  for (const value of Object.values(obj)) {
    if (Array.isArray(value)) {
      if (
        value.some(line =>
          line &&
          typeof line === 'object' &&
          (
            line.code ||
            line.description_code ||
            line.document_code ||
            line.name ||
            line.description ||
            line.document_name
          )
        )
      ) {
        return value;
      }
    }

    if (value && typeof value === 'object') {
      const found = findChecklistLines(value);
      if (found.length) return found;
    }
  }

  return [];
}

function isAttachmentRequired(line) {
  // MAIN BACKEND FIELD
  if (line.is_attachment_required !== undefined) {
    return (
      line.is_attachment_required === true ||
      line.is_attachment_required === 'true' ||
      line.is_attachment_required === 1 ||
      line.is_attachment_required === '1'
    );
  }

  // Fallback names, just in case
  if (line.attachment_required !== undefined) {
    return (
      line.attachment_required === true ||
      line.attachment_required === 'true' ||
      line.attachment_required === 1 ||
      line.attachment_required === '1'
    );
  }

  if (line.required !== undefined) {
    return (
      line.required === true ||
      line.required === 'true' ||
      line.required === 1 ||
      line.required === '1'
    );
  }

  // Safe fallback:
  // If backend does not send any flag, treat as required.
  return true;
}

function isDataRequired(line) {
  if (line.is_data_required !== undefined) {
    return (
      line.is_data_required === true ||
      line.is_data_required === 'true' ||
      line.is_data_required === 1 ||
      line.is_data_required === '1'
    );
  }

  return false;
}

function normalizeLang(lang) {
  const value = String(lang || '').trim().toLowerCase();
  if (value.includes('tamil') || value === 'ta') return 'tamil';
  if (value.includes('tanglish')) return 'tanglish';
  return 'english';
}

function getDocumentGroup(doc) {
  const code = String(doc.description_code || doc.code || '').toLowerCase();
  const label = String(doc.label || doc.name || '').toLowerCase();

  const backendGroup = String(
    doc.document_group ||
    doc.group ||
    doc.category ||
    ''
  ).toLowerCase();

  if (backendGroup.includes('bride')) return 'bride';
  if (backendGroup.includes('groom')) return 'groom';
  if (backendGroup.includes('marriage')) return 'marriage';
  if (backendGroup.includes('common')) return 'marriage';

  if (code.startsWith('bride_') || code.includes('_bride_') || label.includes('bride')) {
    return 'bride';
  }

  if (code.startsWith('groom_') || code.includes('_groom_') || label.includes('groom')) {
    return 'groom';
  }

  return 'marriage';
}

function groupRequiredDocuments(requiredDocs) {
  const groups = {
    bride: [],
    groom: [],
    marriage: [],
    other: []
  };

  for (const doc of requiredDocs) {
    const group = getDocumentGroup(doc);
    if (groups[group]) {
      groups[group].push(doc);
    } else {
      groups.other.push(doc);
    }
  }

  return groups;
}

function buildGroupedDocumentLines(requiredDocs, lang) {
  const groups = groupRequiredDocuments(requiredDocs);
  const sections = [];

  function buildSection(title, docs) {
    if (!docs.length) return '';

    const lines = docs
      .map((doc, index) => `${index + 1}. ${doc.label}`)
      .join('\n');

    return `${title}\n${lines}`;
  }

  if (lang === 'tamil') {
    sections.push(buildSection('👰 மணமகள் ஆவணங்கள்', groups.bride));
    sections.push(buildSection('🤵 மணமகன் ஆவணங்கள்', groups.groom));
    sections.push(buildSection('💍 திருமண ஆவணங்கள்', groups.marriage));
    sections.push(buildSection('📌 மற்ற ஆவணங்கள்', groups.other));
  } else if (lang === 'tanglish') {
    sections.push(buildSection('👰 Bride Documents', groups.bride));
    sections.push(buildSection('🤵 Groom Documents', groups.groom));
    sections.push(buildSection('💍 Marriage Documents', groups.marriage));
    sections.push(buildSection('📌 Other Documents', groups.other));
  } else {
    sections.push(buildSection('👰 Bride Documents', groups.bride));
    sections.push(buildSection('🤵 Groom Documents', groups.groom));
    sections.push(buildSection('💍 Marriage Documents', groups.marriage));
    sections.push(buildSection('📌 Other Documents', groups.other));
  }

  return sections.filter(Boolean).join('\n\n');
}

function checklistFetchFailedMessage(lang) {
  if (lang === 'tamil') {
    return (
      `தற்போது தேவையான ஆவண பட்டியலை பெற முடியவில்லை.\n\n` +
      `எங்கள் குழு சரிபார்த்து உங்களுக்கு தெரிவிக்கும்.`
    );
  }

  if (lang === 'tanglish') {
    return (
      `Ippo required documents list fetch panna mudiyala.\n\n` +
      `Enga team check pannitu update pannuvanga.`
    );
  }

  return (
    `We are unable to fetch the required document checklist right now.\n\n` +
    `Our team will check and update you shortly.`
  );
}

function buildChecklistReadyMessage(requiredDocs, lang) {
  const groupedLines = buildGroupedDocumentLines(requiredDocs, lang);

  if (lang === 'tamil') {
    return (
      `அடுத்ததாக ஆவண பதிவேற்றம் தொடரும்.\n\n` +
      `தேவையான ஆவணங்கள்:\n\n${groupedLines}\n\n` +
      `தயவுசெய்து இந்த ஆவணங்களை தயார் வைத்திருக்கவும்.\n\n` +
      `ஆவண பதிவேற்றத்தை தொடங்க 1 என்று பதிலளிக்கவும்.\n` +
      `பின்னர் பதிவேற்ற 2 என்று பதிலளிக்கவும்.`
    );
  }

  if (lang === 'tanglish') {
    return (
      `Next document collection start pannalam.\n\n` +
      `Required documents:\n\n${groupedLines}\n\n` +
      `Indha documents ready ah vechikonga.\n\n` +
      `Document upload start panna 1 reply pannunga.\n` +
      `Later upload panna 2 reply pannunga.`
    );
  }

  return (
    `Next, we will continue with document collection.\n\n` +
    `Required documents:\n\n${groupedLines}\n\n` +
    `Please keep these documents ready.\n\n` +
    `Reply 1 to start uploading documents.\n` +
    `Reply 2 if you want to upload them later.`
  );
}

function noRequiredDocumentsMessage(lang) {
  if (lang === 'tamil') {
    return (
      `இந்த சேவைக்கு தற்போது பதிவேற்ற வேண்டிய கட்டாய ஆவணங்கள் இல்லை.\n\n` +
      `ஆவண சரிபார்ப்பு நிலையை அறிய 1 என்று பதிலளிக்கவும்.`
    );
  }

  if (lang === 'tanglish') {
    return (
      `Indha service ku ippo upload panna vendiya mandatory documents illa.\n\n` +
      `Document verification status check panna 1 reply pannunga.`
    );
  }

  return (
    `There are no mandatory upload documents required for this service right now.\n\n` +
    `Reply 1 to check your document verification status.`
  );
}

const data = parseSession(previous.session_data || httpInput.session_data);
const lang = normalizeLang(previous.language || httpInput.language || data.language);

const payload = getPayload(httpInput);
const checklist = findChecklistLines(payload);

if (!checklist.length) {
  const reply = checklistFetchFailedMessage(lang);

  data.current_stage = 'document_checklist_fetch_failed';
  data.need_document_checklist = true;
  data.document_collection_completed = false;
  data.awaiting_document_upload_start = false;
  data.awaiting_document_status_check = false;
  data.document_checklist = [];
  data.last_reply = reply;

  return [{
    json: {
      ...previous,
      current_stage: 'document_checklist_fetch_failed',
      language: lang,
      need_document_checklist: true,
      document_collection_completed: false,
      awaiting_document_upload_start: false,
      awaiting_document_status_check: false,
      checklist_debug_payload_keys: Object.keys(payload || {}),
      reply,
      output: reply,
      last_reply: reply,
      session_data: JSON.stringify(data)
    }
  }];
}

const normalizedChecklist = checklist.map((line, index) => {
  const descriptionCode =
    line.description_code ||
    line.code ||
    line.document_code ||
