    line.checklist_name ||
    descriptionCode;

  const attachmentRequired = isAttachmentRequired(line);
  const dataRequired = isDataRequired(line);
  const botStatus = line.bot_status || line.status || 'pending';

  const doc = {
    index,
    description_code: descriptionCode,
    code: descriptionCode,
