    name: label,

    // For file upload flow, required means attachment is required.
    required: attachmentRequired,
    is_attachment_required: attachmentRequired,
    is_data_required: dataRequired,

    bot_status: attachmentRequired === false ? 'skipped_no_attachment_required' : botStatus,
    uploaded: line.uploaded === true || ['uploaded', 'approved'].includes(botStatus),
    upload_later: botStatus === 'upload_later',
    skipped: attachmentRequired === false
  };

  doc.document_group = getDocumentGroup(doc);

  return doc;
});

const requiredDocuments = normalizedChecklist.filter(doc => doc.required === true);
const optionalDocuments = normalizedChecklist.filter(doc => doc.required === false);

const pendingRequiredDocs = requiredDocuments.filter(doc =>
  doc.uploaded !== true &&
  doc.bot_status !== 'approved'
);

let reply = '';
let currentStage = '';

if (pendingRequiredDocs.length > 0) {
  currentStage = 'document_checklist_ready';

const checklistReply = buildChecklistReadyMessage(pendingRequiredDocs, lang);

const paymentStatusReply =
  previous.payment_status_reply ||
  data.payment_status_reply ||
  '';

reply = paymentStatusReply
  ? `${paymentStatusReply}\n\n${checklistReply}`
