  data.current_stage = currentStage;
  data.document_checklist = normalizedChecklist;
  data.required_documents = requiredDocuments;
  data.optional_documents = optionalDocuments;
  data.pending_required_documents = pendingRequiredDocs;
  data.awaiting_document_upload_start = true;
  data.document_collection_started = false;
  data.document_collection_completed = false;
  data.has_pending_later_documents = false;
  data.awaiting_document_status_check = false;
  data.expected_document_code = '';
  data.expected_document_label = '';
