  data.required_documents = requiredDocuments;
  data.optional_documents = optionalDocuments;
  data.pending_required_documents = [];
  data.awaiting_document_upload_start = false;
  data.document_collection_started = false;
  data.document_collection_completed = true;
  data.has_pending_later_documents = false;
  data.awaiting_document_status_check = true;
  data.expected_document_code = '';
  data.expected_document_label = '';
  data.current_document_code = '';
  data.current_document_label = '';
  data.last_reply = reply;
}

return [{
  json: {
    ...previous,
    current_stage: currentStage,
    language: lang,

    document_checklist: normalizedChecklist,
    required_documents: requiredDocuments,
    optional_documents: optionalDocuments,
    pending_required_documents: pendingRequiredDocs,

    awaiting_document_upload_start: data.awaiting_document_upload_start,
    document_collection_started: data.document_collection_started,
    document_collection_completed: data.document_collection_completed,
